function messageTextFromWrap(wrap) {
  if (!wrap) return '';
  var bubble = wrap.querySelector('.bubble');
  return bubble ? String(bubble.innerText || bubble.textContent || '').replace(/\n{3,}/g, '\n\n').trim() : '';
}

function setMessageActionStatus(wrap, value) {
  var status = wrap && wrap.querySelector('.message-action-status');
  if (!status) return;
  status.textContent = value || '';
  clearTimeout(status._clearTimer);
  status._clearTimer = setTimeout(function() { status.textContent = ''; }, 1800);
}

async function copyTextSafely(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(text);
  var area = document.createElement('textarea');
  area.value = text; area.setAttribute('readonly', ''); area.style.position = 'fixed'; area.style.opacity = '0';
  document.body.appendChild(area); area.select(); document.execCommand('copy'); area.remove();
}

var inlineFeedbackInFlight = {};
async function recordInlineMessageFeedback(kind, text) {
  if (!currentUser || !SUPABASE_TOKEN) return false;
  var reference = 'Response reference: ' + simpleStableHash(String(text || ''));
  var lockKey = currentUser.id + '|' + reference;
  if (inlineFeedbackInFlight[lockKey]) return false;
  inlineFeedbackInFlight[lockKey] = true;
  try {
    var ownedFilter = 'user_id=eq.' + encodeURIComponent(currentUser.id) + '&page=eq.marg_chat_message&text=eq.' + encodeURIComponent(reference);
    var previous = await sbFetch('feedback?select=id,selected&' + ownedFilter + '&order=created_at.desc&limit=1', 'GET');
    if (!previous || previous.error) return false;
    var row = previous.data && previous.data[0];
    if (row && row.selected === 'message_' + kind) return true;
    var result = await sbFetch(row ? 'feedback?id=eq.' + encodeURIComponent(row.id) + '&' + ownedFilter : 'feedback', row ? 'PATCH' : 'POST', {
      user_id:currentUser.id,
      selected:'message_' + kind,
      text:reference,
      page:'marg_chat_message',
      sessions:studentProfile ? studentProfile.sessionsCount || 0 : 0
    });
    var saved = !!(result && result.ok);
    if (saved && typeof captureMargResponseReview === 'function') {
      captureMargResponseReview({
        source:kind === 'helpful' ? 'helpful' : 'not_helpful',
        assistantText:text,
        failureLabel:kind === 'helpful' ? null : 'other',
        allowModelImprovement:false
      });
    }
    return saved;
  } catch(e) { return false; }
  finally { delete inlineFeedbackInFlight[lockKey]; }
}

var responseRegenerationInFlight = false;

function applyRegeneratedReplyGuard(response, diagnosis) {
  if (diagnosis && diagnosis.hintOnly) return guardHintOnlyResponse(response);
  var text = convertLatexToPlainText(reduceAssistantStyleLanguage(enforceIndiaTimeGreeting(correctCalendarReferences(String(response || ''))))).trim();
  text = simplifyMentorLanguage(text);
  text = guardPromptInstructionLeak(text, diagnosis);
  text = guardSectionalEvidenceOverclaim(text, diagnosis);
  text = guardMockScoreArithmeticOverclaim(text, diagnosis);
  text = guardUnusableExerciseEvidence(text, diagnosis);
  text = guardVagueMentorAdvice(text, diagnosis);
  text = guardMalformedChatExercise(text);
  text = guardMissingExerciseControl(text);
  text = guardPastedAnswerChoiceIntegrity(text, diagnosis);
  text = guardExerciseAbilityOverclaim(text);
  text = guardAnswerVerdictConsistency(text, diagnosis);
  if (diagnosis && diagnosis.gradingIntegrityRepaired) return finalizeMentorSavedText(stripInternalMentorTags(text).trim(), diagnosis);
  text = guardEvidenceRefinementLanguage(text, diagnosis);
  text = formatMultiAnswerReview(text, diagnosis);
  text = guardTimeAllocationArithmetic(text);
  // Regeneration is a rewrite of one existing bubble. Deliberately do not run
  // the normal progression/profile/mission closers here: those can manufacture
  // a new exercise or question that was not present in the answer being revised.
  // Arithmetic, certainty and question budget still apply to the saved rewrite.
  return finalizeMentorSavedText(stripInternalMentorTags(text).trim(), diagnosis);
}

function latestVisibleAssistantHistoryIndex() {
  for (var i = conversationHistory.length - 1; i >= 0; i--) {
    if (conversationHistory[i] && conversationHistory[i].role === 'assistant' && !isInternalMemoryMessage(conversationHistory[i])) return i;
  }
  return -1;
}

function isLatestAssistantBubble(wrap) {
  var assistantWraps = Array.prototype.slice.call(document.querySelectorAll('#messages .msg-wrap.marg')).filter(function(item) {
    return item.querySelector('.bubble') && !item.querySelector('.typing-bubble');
  });
  return assistantWraps.length > 0 && assistantWraps[assistantWraps.length - 1] === wrap;
}

async function persistRegeneratedAssistantMessage(historyItem, previousContent, nextContent) {
  if (!currentUser || !SUPABASE_TOKEN || !historyItem) return false;
  var userId = currentUser.id;
  var plainPreviousContent=previousContent,expectedThreadId=historyItem.threadId||'legacy';
  if(typeof encodeTopicChatContent==='function'){previousContent=encodeTopicChatContent(previousContent,historyItem);nextContent=encodeTopicChatContent(nextContent,historyItem);}
  var rowId = historyItem.id || null;
  try {
    if (!rowId) {
      var result = await sbFetch('chats?select=id,content&user_id=eq.' + userId + '&role=eq.assistant&order=created_at.desc&limit=20', 'GET');
      var rows = result && result.data || [];
      var matches = rows.filter(function(row) {
        if(typeof decodeTopicChatRow==='function'){var decoded=decodeTopicChatRow(row);return decoded.threadId===expectedThreadId&&decoded.content===String(plainPreviousContent||'');}
        return String(row.content||'')===String(previousContent||'');
      });
      var match = matches.length === 1 ? matches[0] : null;
      rowId = match && match.id || null;
    }
    if (!rowId || !currentUser || currentUser.id !== userId) return false;
    historyItem.id = rowId;
    if (!enqueueChatWrite({id:rowId,user_id:userId,role:'assistant',content:nextContent,created_at:historyItem.createdAt || new Date().toISOString()}, 'update')) {
      var updated = await sbFetch('chats?id=eq.' + encodeURIComponent(rowId) + '&user_id=eq.' + encodeURIComponent(userId), 'PATCH', { content:nextContent });
      return !!(updated && updated.ok);
    }
    return await flushChatOutbox(userId);
  } catch(e) {
    console.error('Regenerated response save failed:', e);
    return false;
  }
}

function saveResponseVersionsForBrowser(historyItem, versions, ownerId) {
  if (!currentUser || (ownerId && currentUser.id !== ownerId) || !historyItem || !historyItem.id || !Array.isArray(versions)) return false;
  try {
    var key = getUserScopedKey('marg_response_versions');
    var saved = JSON.parse(localStorage.getItem(key) || '{}');
    if (!saved || Array.isArray(saved) || typeof saved !== 'object') saved = {};
    saved[historyItem.id] = versions.filter(function(value) { return typeof value === 'string'; }).slice(-10);
    var ids = Object.keys(saved);
    ids.slice(0, Math.max(0, ids.length - 100)).forEach(function(id) { delete saved[id]; });
    localStorage.setItem(key, JSON.stringify(saved));
    return true;
  } catch(e) { return false; }
}

function restoreResponseVersionsForBrowser(wrap, historyItem) {
  if (!currentUser || !wrap || !historyItem || !historyItem.id || historyItem.role !== 'assistant') return false;
  try {
    var saved = JSON.parse(localStorage.getItem(getUserScopedKey('marg_response_versions')) || '{}');
    var versions = saved && saved[historyItem.id];
    if (!Array.isArray(versions) || versions.length < 2 || !versions.every(function(value) { return typeof value === 'string'; })) return false;
    var selected = versions.indexOf(historyItem.content);
    if (selected < 0) return false; // Never replace a newer reply from another device.
    wrap._margResponseVersions = versions;
    wrap._margHistoryItem = historyItem;
    ensureResponseVersionNavigator(wrap);
    renderAssistantVersion(wrap, selected);
    return true;
  } catch(e) { return false; }
}

function renderAssistantVersion(wrap, versionIndex) {
  if (!wrap || !Array.isArray(wrap._margResponseVersions) || !wrap._margResponseVersions.length) return;
  var index = Math.max(0, Math.min(Number(versionIndex) || 0, wrap._margResponseVersions.length - 1));
  wrap._margResponseVersionIndex = index;
  var content = wrap._margResponseVersions[index];
  var bubble = wrap.querySelector('.bubble');
  if (!bubble) return;
  wrap.classList.remove('passage-message');
  bubble.removeAttribute('style');
  bubble.innerHTML = renderGroundingSourcesForChat(renderMentorStructuredText(content));
  decoratePassageMessage(wrap);
  // This bubble can be older than the latest reply. Never edit a different turn.
  var historyItem = wrap._margHistoryItem;
  if (historyItem && conversationHistory.indexOf(historyItem) >= 0) historyItem.content = content;
  var nav = wrap.querySelector('.message-version-nav');
  if (nav) {
    var label = nav.querySelector('.message-version-count');
    if (label) label.textContent = (index + 1) + ' / ' + wrap._margResponseVersions.length;
    var previous = nav.querySelector('[data-version-step="-1"]');
    var next = nav.querySelector('[data-version-step="1"]');
    if (previous) previous.disabled = index === 0;
    if (next) next.disabled = index === wrap._margResponseVersions.length - 1;
  }
}

function ensureResponseVersionNavigator(wrap) {
  var actions = wrap && wrap.querySelector('.message-actions');
  if (!actions || wrap.querySelector('.message-version-nav')) return;
  var nav = document.createElement('span');
  nav.className = 'message-version-nav';
  nav.innerHTML = '<button type="button" data-version-step="-1" aria-label="Previous response version">‹</button><span class="message-version-count"></span><button type="button" data-version-step="1" aria-label="Next response version">›</button>';
  nav.addEventListener('click', function(event) {
    var button = event.target.closest('[data-version-step]');
    if (!button) return;
    var item = wrap._margHistoryItem;
    var oldContent = item && item.content;
    renderAssistantVersion(wrap, (wrap._margResponseVersionIndex || 0) + Number(button.getAttribute('data-version-step')));
    if (item && conversationHistory.indexOf(item) >= 0) persistRegeneratedAssistantMessage(item, oldContent, item.content).then(function(saved) {
      setMessageActionStatus(wrap, saved ? 'Version saved' : 'Version changed; account sync pending');
    });
  });
  actions.insertBefore(nav, actions.querySelector('.message-action-status'));
  renderAssistantVersion(wrap, wrap._margResponseVersions.length - 1);
}

async function regenerateAssistantMessage(wrap) {
  var regenerationOwnerId = currentUser && currentUser.id;
  if (responseRegenerationInFlight || isLoading) {
    setMessageActionStatus(wrap, 'Marg is still responding');
    return;
  }
  if (!isLatestAssistantBubble(wrap)) {
    setMessageActionStatus(wrap, 'Regenerate the latest reply');
    return;
  }
  var historyIndex = latestVisibleAssistantHistoryIndex();
  var historyItem = historyIndex >= 0 ? conversationHistory[historyIndex] : null;
  if (!historyItem) {
    setMessageActionStatus(wrap, 'Reply context unavailable');
    return;
  }
  var userMessage = '';
  for (var i = historyIndex - 1; i >= 0; i--) {
    if (conversationHistory[i] && conversationHistory[i].role === 'user' && !isInternalMemoryMessage(conversationHistory[i])) {
      userMessage = String(conversationHistory[i].content || '');
      break;
    }
  }
  if (!userMessage) {
    setMessageActionStatus(wrap, 'Reply context unavailable');
    return;
  }
  var previousContent = String(historyItem.content || '');
  wrap._margHistoryItem = historyItem;
  var versions = Array.isArray(wrap._margResponseVersions) ? wrap._margResponseVersions.slice() : [previousContent];
  responseRegenerationInFlight = true;
  var retryButton = wrap.querySelector('[data-message-action="retry"]');
  if (retryButton) retryButton.disabled = true;
  wrap.classList.add('regenerating-response');
  setMessageActionStatus(wrap, 'Writing another version…');
  try {
    var diagnosis = buildDiagnosisDirective(userMessage);
    var regenerationInstruction = '\n\nREWRITE-ONLY CONTRACT: You are revising one existing answer, not continuing the conversation. Keep its exact purpose, conclusion, factual claims and next step. Make it clearer and more natural, but do not add a heading, diagnosis, exercise, mission, action step, timeline, follow-up question or new advice that the existing answer did not contain. Do not turn a short answer into a lesson. Return only the rewritten answer.';
    var regenerationMaterial = 'ORIGINAL USER MESSAGE:\n' + userMessage + '\n\nEXISTING ANSWER TO REWRITE:\n' + previousContent;
    var request = buildGeminiRequest(
      SYSTEM_PROMPT + getDateContext() + getGeneratedExerciseMemoryContext(userMessage) + regenerationInstruction,
      [{ role:'user', content:regenerationMaterial }],
      getMentorResponseMaxTokens(diagnosis.diagnosis)
    );
    var response = await fetchWithTimeout(WORKER_URL, {
      method:'POST', headers:{ 'Content-Type':'application/json' }, body:JSON.stringify(request)
    }, getMentorRequestTimeout(diagnosis.diagnosis, false));
    if (!response.ok) throw new Error('Worker status ' + response.status);
    var payload = await response.json();
    var regeneratedSource = selectMentorModelText(payload);
    if (regeneratedSource == null) throw new Error('Regenerated mentor output hit the token ceiling');
    var regenerated = applyRegeneratedReplyGuard(preventStructuredOutputLeak(regeneratedSource), diagnosis.diagnosis);
    var previousSourceMarkers = previousContent.match(MARG_GROUNDING_SOURCE_PATTERN) || [];
    if (previousSourceMarkers.length && !/\[MARG_SOURCES:/.test(regenerated)) regenerated += '\n' + previousSourceMarkers.join('');
    MARG_GROUNDING_SOURCE_PATTERN.lastIndex = 0;
    if (!regenerated.trim()) throw new Error('Empty regenerated response');
    versions.push(regenerated);
    wrap._margResponseVersions = versions;
    historyItem.content = regenerated;
    var versionSaved = await persistRegeneratedAssistantMessage(historyItem, previousContent, regenerated);
    saveResponseVersionsForBrowser(historyItem, versions, regenerationOwnerId);
    ensureResponseVersionNavigator(wrap);
    renderAssistantVersion(wrap, versions.length - 1);
    setMessageActionStatus(wrap, versionSaved ? 'New version saved' : 'New version; account sync pending');
  } catch(e) {
    console.error('Response regeneration failed:', e);
    setMessageActionStatus(wrap, e && e.name === 'AbortError' ? 'Regeneration timed out' : 'Could not regenerate');
  } finally {
    responseRegenerationInFlight = false;
    if (retryButton) retryButton.disabled = false;
    wrap.classList.remove('regenerating-response');
  }
}

function openPassageReadingMode(wrap) {
  var passage = wrap && wrap.querySelector('.passage-reading-content');
  if (!passage) return;
  var overlay = document.createElement('div');
  overlay.className = 'reading-focus-overlay';
  overlay.setAttribute('role', 'dialog'); overlay.setAttribute('aria-modal', 'true'); overlay.setAttribute('aria-label', 'Passage reading mode');
  overlay.innerHTML = '<div class="reading-focus-bar"><span>Reading mode</span><div class="reading-focus-actions"><button type="button" data-reader-action="smaller" aria-label="Decrease text size">A−</button><button type="button" data-reader-action="larger" aria-label="Increase text size">A+</button><button type="button" data-reader-action="theme">Paper</button><button class="reading-focus-close" type="button" data-reader-action="close">Close</button></div></div><div class="reading-focus-scroll"><div class="passage-reading-content">' + passage.innerHTML + '</div></div>';
  var oldOverflow = document.body.style.overflow;
  function close() { document.body.style.overflow = oldOverflow; overlay.remove(); }
  overlay.addEventListener('click', function(event) {
    var button = event.target.closest('[data-reader-action]');
    if (!button) return;
    var action = button.getAttribute('data-reader-action');
    if (action === 'close') { close(); return; }
    if (action === 'theme') { overlay.classList.toggle('paper'); button.textContent = overlay.classList.contains('paper') ? 'Dark' : 'Paper'; return; }
    var current = parseFloat(localStorage.getItem('marg_reader_scale') || '1');
    current += action === 'larger' ? 0.1 : -0.1;
    current = Math.max(.9, Math.min(1.35, current));
    localStorage.setItem('marg_reader_scale', current.toFixed(2));
    document.documentElement.style.setProperty('--marg-reader-scale', current.toFixed(2));
  });
  overlay.addEventListener('keydown', function(event) { if (event.key === 'Escape') close(); });
  document.body.style.overflow = 'hidden'; document.body.appendChild(overlay);
  var closeButton = overlay.querySelector('.reading-focus-close'); if (closeButton) closeButton.focus();
}

function decoratePassageMessage(wrap) {
  var bubble = wrap && wrap.querySelector('.bubble');
  if (!bubble || bubble.querySelector('.passage-reading-content')) return false;
  var savedReaderScale = parseFloat(localStorage.getItem('marg_reader_scale') || '1');
  if (Number.isFinite(savedReaderScale)) document.documentElement.style.setProperty('--marg-reader-scale', Math.max(.9, Math.min(1.35, savedReaderScale)).toFixed(2));
  var text = String(bubble.innerText || bubble.textContent || '').replace(/\r/g, '').replace(/^\s*\*{3}\s*$/gm, '').trim();
  if (text.length < 650) return false;
  // Recognise all RC surfaces used by Marg: a raw PASSAGE block after a short
  // instruction, and the guided "CAT RC · Hard" format. The old start-only
  // check missed both and left 500-word passages inside the normal chat font.
  var passageMarker = text.match(/(?:^|\n)\s*\*{0,3}\s*PASSAGE\s*:?[ \t]*(?:\*{0,3}\s*)?(?:\n|$)/i);
  var titleMarker = !passageMarker ? text.match(/^\s*CAT\s+RC\s*[·|—-][^\n]*\n+/i) : null;
  if (!passageMarker && !titleMarker && !/^(?:CAT[- ]LEVEL\s+)?(?:RC\s+)?PASSAGE\b/i.test(text)) return false;
  var bodyStart = passageMarker ? passageMarker.index + passageMarker[0].length : titleMarker ? titleMarker[0].length : 0;
  var body = text.slice(bodyStart).replace(/^(?:CAT[- ]LEVEL\s+)?(?:RC\s+)?PASSAGE\s*:?[ \t]*/i, '').trim();
  var questionMatch = body.match(/\n\s*(?=QUESTIONS?\s*:?(?:\n|$)|(?:Q(?:UESTION)?\s*)?1\s*[.):])/i);
  var splitAt = questionMatch ? questionMatch.index : -1;
  var passageText = (splitAt >= 0 ? body.slice(0, splitAt) : body).trim();
  var questionsText = splitAt >= 0 ? body.slice(splitAt).replace(/^\s*QUESTIONS?\s*:?[ \t]*(?:\n|$)/i, '').trim() : '';
  if (passageText.length < 450) return false;
  var paragraphs = passageText.split(/\n\s*\n|(?<=\.)\s+(?=(?:However|Yet|But|This|These|Such|Instead|Although|Nevertheless|Consequently|In contrast)\b)/).map(function(item) { return item.trim(); }).filter(Boolean);
  bubble.innerHTML = '<div class="passage-reader-head"><span class="passage-reader-label">CAT reading passage</span><div class="passage-reader-tools"><button class="passage-reader-tool" type="button" data-open-reader>Focus · Aa</button></div></div><div class="passage-reading-content">' + paragraphs.map(function(item) { return '<p>' + escapeVisualText(item) + '</p>'; }).join('') + '</div>' + (questionsText ? '<div class="passage-questions"><div class="passage-questions-label">Questions</div>' + renderMentorStructuredText(questionsText) + '</div>' : '');
  wrap.classList.add('passage-message');
  var openButton = bubble.querySelector('[data-open-reader]'); if (openButton) openButton.addEventListener('click', function() { openPassageReadingMode(wrap); });
  return true;
}

function addMessageActions(wrap, role) {
  if (!wrap || wrap.querySelector('.message-actions')) return;
  var bubble = wrap.querySelector('.bubble');
  if (!bubble || bubble.classList.contains('typing-bubble')) return;
  var stack = bubble.parentElement && bubble.parentElement.classList.contains('message-stack') ? bubble.parentElement : null;
  if (!stack) {
    stack = document.createElement('div'); stack.className = 'message-stack';
    bubble.parentNode.insertBefore(stack, bubble); stack.appendChild(bubble);
  }
  var hasSources = !!bubble.querySelector('.marg-source-dot');
  var actions = document.createElement('div'); actions.className = 'message-actions';
  actions.innerHTML = role === 'user'
    ? messageActionButton('copy', 'Copy message') + messageActionButton('edit', 'Edit and resend') + messageActionButton('share', 'Share message') + '<span class="message-action-status" aria-live="polite"></span>'
    : messageActionButton('copy', 'Copy response') + messageActionButton('listen', 'Read aloud') + messageActionButton('up', 'Helpful') + messageActionButton('down', 'Not helpful') + messageActionButton('share', 'Share response') + messageActionButton('retry', 'Ask Marg to answer again') + (hasSources ? messageActionButton('sources', 'View sources') : '') + messageActionButton('report', 'Report response') + '<span class="message-action-status" aria-live="polite"></span>';
  actions.addEventListener('click', async function(event) {
    var button = event.target.closest('[data-message-action]'); if (!button) return;
    var action = button.getAttribute('data-message-action'); var text = messageTextFromWrap(wrap);
    if (action === 'copy') { await copyTextSafely(text); setMessageActionStatus(wrap, 'Copied'); }
    else if (action === 'edit') {
      var input = document.getElementById('user-input'); if (!input) return;
      input.value = text; input.dispatchEvent(new Event('input', { bubbles:true })); focusComposer({ userInitiated:true }); setMessageActionStatus(wrap, 'Ready to edit');
    } else if (action === 'share') {
      try { if (navigator.share) await navigator.share({ title:'Marg CAT mentor', text:text }); else { await copyTextSafely(text); setMessageActionStatus(wrap, 'Copied to share'); } } catch(e) { if (e && e.name !== 'AbortError') setMessageActionStatus(wrap, 'Could not share'); }
    } else if (action === 'listen') {
      if (!window.speechSynthesis) { setMessageActionStatus(wrap, 'Listen unavailable'); return; }
      if (button.classList.contains('active')) { window.speechSynthesis.cancel(); button.classList.remove('active'); setMessageActionStatus(wrap, 'Stopped'); return; }
      window.speechSynthesis.cancel(); var utterance = new SpeechSynthesisUtterance(text); utterance.lang = 'en-IN'; utterance.rate = .94;
      utterance.onend = function() { button.classList.remove('active'); }; window.speechSynthesis.speak(utterance); button.classList.add('active'); setMessageActionStatus(wrap, 'Reading');
    } else if (action === 'up' || action === 'down') {
      var reactionButtons = actions.querySelectorAll('[data-message-action="up"],[data-message-action="down"]');
      reactionButtons.forEach(function(item) { item.disabled = true; });
      try {
        var saved = await recordInlineMessageFeedback(action === 'up' ? 'helpful' : 'not_helpful', text);
        if (saved) { reactionButtons.forEach(function(item) { item.classList.remove('active'); }); button.classList.add('active'); }
        setMessageActionStatus(wrap, saved ? 'Thanks' : 'Could not save—try again');
      } finally { reactionButtons.forEach(function(item) { item.disabled = false; }); }
    } else if (action === 'retry') {
      regenerateAssistantMessage(wrap);
    } else if (action === 'sources') {
      var firstSource = bubble.querySelector('.marg-source-dot'); if (firstSource) firstSource.click();
    } else if (action === 'report') {
      feedbackSelected = 'Report a response'; var feedbackText = document.getElementById('feedback-text'); if (feedbackText) feedbackText.value = 'Response reference: ' + simpleStableHash(text) + '\n'; showFeedback();
    }
  });
  stack.appendChild(actions);
}

function sanitizeRenderedChatHtml(html) {
  var value = String(html === undefined || html === null ? '' : html);
  if (typeof document === 'undefined' || !document.createElement) return escapeChatHtml(value);
  var template = document.createElement('template');
  template.innerHTML = value;
  template.content.querySelectorAll('script,style,iframe,object,embed,form,meta,link,base').forEach(function(node) { node.remove(); });
  var trustedClickInvocation = /^(?:chooseArticleRCOption|choosePathDiscuss|choosePathPractice|closePushReminderCard|closeTimedTest|confirmSubmitTimedTest|goToArticleRCQuestion|goToChatFromTimedTest|goToTimedTestQuestion|loadDailyPractice|moveArticleRCQuestion|nextQuestion|openArticleRCPassageFocus|openCheckedTimedRecovery|openPreviousMockAnalysis|prevQuestion|removePendingImageAttachment|retryArticleRCGeneration|retryTimedTest|reviewLatestPracticeWithMarg|selectAnswer|selectOption|selectPracticeTopic|selectQACategory|selectTimedTestAnswer|sendQuick|showQACategoryPicker|startLogin|submitArticleRCAttempt|submitFeedback|switchPracticeTab|toggleArticleRCPassage|tryAnotherArticleRC|useVerifiedPracticeRecovery)\s*\(\s*(?:(?:-?\d+(?:\.\d+)?|true|false|null|'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*")\s*(?:,\s*(?:-?\d+(?:\.\d+)?|true|false|null|'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*")\s*)*)?\)\s*;?$/;
  template.content.querySelectorAll('*').forEach(function(node) {
    Array.prototype.slice.call(node.attributes || []).forEach(function(attribute) {
      var name = String(attribute.name || '').toLowerCase();
      var attrValue = String(attribute.value || '').trim();
      var allowedClick = name === 'onclick' && trustedClickInvocation.test(attrValue);
      if ((/^on/.test(name) && !allowedClick) || name === 'srcdoc' || ((name === 'href' || name === 'src' || name === 'xlink:href') && /^\s*(?:javascript|vbscript):/i.test(attrValue))) {
        node.removeAttribute(attribute.name);
      }
    });
    if (node.tagName === 'A') {
      node.setAttribute('rel', 'noopener noreferrer');
      if (node.getAttribute('target') !== '_blank') node.removeAttribute('target');
    }
  });
  return template.innerHTML;
}

function addMessage(role, html, showAvatar) {
  ensureMessageExperienceStyles();
  if (showAvatar === undefined) showAvatar = true;
  if (role === 'marg' && typeof html === 'string') html = convertLatexToPlainText(stripInternalMentorTags(html));
  // Strip markdown from ALL Marg responses at the source
  if (role === 'marg' && html && typeof html === 'string' && !html.includes('<div') && !html.includes('<button')) {
    html = html
      .replace(/\*\*(.*?)\*\*/g, '$1')
      .replace(/\*(.*?)\*/g, '$1')
      .replace(/^#{1,3}\s+/gm, '')
      .replace(/^[-•*]\s+/gm, '')
      .replace(/^>\s+/gm, '')
      .replace(/---+/g, '')
      .replace(/===+/g, '')
      .replace(/\[OPTIONS:[^\]]*\]/g, '').replace(/\[START_TEST:[^\]]*\]/g, '').replace(/\[PRACTICE_LOG:[^\]]*\]/g, '')
      .replace(/\[CONTEXT:[^\]]*\]/g, '')
      .replace(/👇/g, '')
      .replace(/👋/g, '')
      .replace(/\bGo\.\s*(<br>|$)/gm, '')
      .replace(/^\d+\.\s+/gm, '')
      .replace(/Here's what (to do|I can do|happens|what you need)[^.]*\./gi, '')
      .replace(/Here's (your task|the plan|the fix|the thing)[^.]*\./gi, '')
      .replace(/That's it\.?/gi, '')
      .replace(/Moving forward[^.]*\./gi, '')
      .replace(/Real question[^.]*:/gi, '')
      .replace(/\n\n/g, '<br><br>')
      .replace(/\n/g, '<br>')
      .trim();
  }
  html = sanitizeRenderedChatHtml(html);
  const container = document.getElementById('messages');
  const wrap = document.createElement('div');
  wrap.className = 'msg-wrap ' + role + ' fade-in';
  if (role === 'marg' && showAvatar) {
    wrap.innerHTML = '<div class="avatar"><img src="' + LOGO_ICON + '" alt="M"></div><div class="bubble">' + html + '</div>';
  } else if (role === 'user') {
    wrap.innerHTML = '<div class="bubble">' + html + '</div>';
  } else {
    wrap.innerHTML = '<div class="bubble">' + html + '</div>';
    wrap.style.marginLeft = '38px';
  }
  container.appendChild(wrap);
  if (role === 'marg') decoratePassageMessage(wrap);
  if (role === 'marg' || role === 'user') addMessageActions(wrap, role);
  if (!isRestoringConversation) scrollChatToLatest();
  return wrap;
}

function addOnboardingCard(step) {
  const container = document.getElementById('messages');
  const card = document.createElement('div');
  card.style.marginLeft = '38px'; card.className = 'fade-in'; card.id = 'onboard-' + step;
  const opts = onboardingFlow[step].options.map(function(o) { return '<button class="opt-btn" onclick="selectOption(\'' + o.replace(/'/g, "\\'") + '\', ' + step + ')">' + o + '</button>'; }).join('');
  card.innerHTML = '<div class="onboard-card"><div class="options-grid">' + opts + '</div></div>';
  container.appendChild(card);
  scrollChatToLatest();
}

function selectOption(value, step) {
  const card = document.getElementById('onboard-' + step);
  if (card) { card.querySelectorAll('.opt-btn').forEach(function(b) { b.disabled = true; b.style.opacity = b.textContent === value ? '1' : '0.3'; if (b.textContent === value) b.classList.add('selected'); }); }
  studentProfile[onboardingFlow[step].key] = value;
  addMessage('user', value);
  const followUp = onboardingFlow[step].followUp;
  if (followUp && followUp[value]) { setTimeout(function() { addMessage('marg', followUp[value]); proceedOnboarding(step); }, 600); }
  else { proceedOnboarding(step); }
}

function proceedOnboarding(step) {
  const nextStep = step + 1;
  if (nextStep < onboardingFlow.length) { setTimeout(function() { onboardingStep = nextStep; addMessage('marg', onboardingFlow[nextStep].message); addOnboardingCard(nextStep); }, 800); }
  else { setTimeout(finishOnboarding, 800); }
}

async function finishOnboarding() {
  onboardingComplete = true;
  await saveProfile();
  recordEngagementEvent('onboarding_completed', { flow:'legacy-card' }, 'onboarding-v1');
  showBottomNav();
  if (!schedulePendingDeepLinkQuestionDispatch(300)) showPathChoiceScreen();
}

function showPathChoiceScreen() {

  if (window._askMargQuestion) {
    var question = window._askMargQuestion;
    window._askMargQuestion = null;
    setTimeout(async function() {
      addMessage('user', question);
      conversationHistory.push({ role: 'user', content: question });
      if (!isGuestMode) saveChatMessage('user', question);
      showTyping();
      try {
        var res = await fetchWithTimeout(WORKER_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(buildGeminiRequest(
            SYSTEM_PROMPT + getDateContext() + profileContext,
            cleanHistory(conversationHistory),
            1500
          ))
        }, 45000);
        var data = await res.json();
        var reply = getGeminiText(data);
        hideTyping();
        if (reply) {
          var cleanReply = reply.replace(/\[OPTIONS:[^\]]*\]/g, '').replace(/\[START_TEST:[^\]]*\]/g, '').replace(/\[PRACTICE_LOG:[^\]]*\]/g, '').replace(/\[CONTEXT:[^\]]*\]/g, '').replace(/\*\*(.*?)\*\*/g, '$1').replace(/\*(.*?)\*/g, '$1').replace(/^#{1,3}\s+/gm, '').replace(/^[-•*]\s+/gm, '').replace(/---+/g, '').trim();
          addMessage('marg', cleanReply.replace(/\n\n/g, '<br><br>').replace(/\n/g, '<br>'));
          conversationHistory.push({ role: 'assistant', content: reply });
          if (!isGuestMode) saveChatMessage('assistant', cleanReply);
        }
      } catch(e) {
        hideTyping();
        addMessage('marg', e && e.name === 'AbortError' ? 'That took longer than expected — mind asking again?' : 'Yaar, connection issue. Please try again in a moment.');
      }
    }, 800);
    return;
  }

  if (window._pendingAttempt) {
    startFromAttemptContext(window._pendingAttempt);
    window._pendingAttempt = null;
    return;
  }

  const messages = document.getElementById('messages');
  const choiceHtml = '<div style="margin:8px 0;display:flex;flex-direction:column;gap:8px;"><button onclick="choosePathDiscuss()" style="background:var(--surface2);border:1.5px solid var(--border2);border-radius:12px;padding:14px 16px;font-family:DM Sans,sans-serif;font-size:14px;color:var(--text);cursor:pointer;text-align:left;transition:border-color 0.2s;">💬 Discuss my strategy with Marg</button><button onclick="choosePathPractice()" style="background:var(--surface2);border:1.5px solid var(--border2);border-radius:12px;padding:14px 16px;font-family:DM Sans,sans-serif;font-size:14px;color:var(--text);cursor:pointer;text-align:left;transition:border-color 0.2s;">📝 Start with today\'s practice</button></div>';
  messages.innerHTML += choiceHtml;
  messages.scrollTop = messages.scrollHeight;
}

async function startFromAttemptContext(attempt) {

  await savePracticeAttempt(attempt);


  document.getElementById('user-input').disabled = false;
  document.getElementById('send-btn').disabled = false;


  var contextMsg = '';
  if (attempt.type === 'rc') {
    contextMsg = 'I just attempted today\'s RC on Marg\'s daily practice page. I ' + (attempt.correct ? 'got it right' : 'got it wrong — I picked option ' + attempt.selectedOption) + '. The question was about: ' + attempt.topic + '. The trap type was: ' + (attempt.trapType || 'not identified') + '. Based on this, can you start my preparation with a quick analysis of what this tells you about my VARC approach?';
  } else if (attempt.type === 'dilr') {
    contextMsg = 'I just attempted a DILR set on Marg\'s daily practice page. I ' + (attempt.correct ? 'got it right' : 'got it wrong') + '. The set type was: ' + attempt.setType + '. Based on this, can you start my preparation with what this tells you about my DILR approach?';
  } else if (attempt.type === 'qa') {
    contextMsg = 'I just attempted a QA question on Marg\'s daily practice page. I ' + (attempt.correct ? 'got it right' : 'got it wrong') + '. Topics: ' + attempt.topics + '. Common mistake: ' + (attempt.commonMistake || 'not identified') + '. Based on this, can you start my preparation with what this tells you about my QA approach?';
  }


  conversationHistory.push({ role: 'user', content: contextMsg });
  showTyping();

  try {
    var res = await fetchWithTimeout(WORKER_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(buildGeminiRequest(
        SYSTEM_PROMPT + getDateContext() + '\n\nIMPORTANT: This user arrived after attempting a practice question. Lead with one specific inference from that live attempt, explain the next correction briefly, and give one immediate follow-up action. Do not start profile setup or ask for background details.',
        cleanHistory(conversationHistory),
        400
      ))
    }, 45000);
    var data = await res.json();
    var response = correctCalendarReferences(getGeminiText(data));
    hideTyping();
    if (response) {
      addMargMessage(response);
      conversationHistory.push({ role: 'assistant', content: response });
    }
  } catch(e) {
    hideTyping();
    var fallbackInsight = attempt.correct
      ? 'You converted the setup correctly. The next thing I want to test is whether that method survives a less familiar version—let\'s do one variation now.'
      : 'The miss gives us useful evidence: the first suspect is your setup choice, not your ability. Let\'s rebuild the same decision on one cleaner variation now.';
    addMentorLeadMessage(fallbackInsight);
  }
}

async function savePracticeAttempt(attempt) {
  if (!currentUser || !SUPABASE_TOKEN) return;
  try {

    if (!attempt.correct && attempt.trapType) {
      var observedPattern = recordBehaviorPattern(attempt.type, attempt.trapType, attempt.question || attempt.commonMistake || '', 'daily-practice');
      // One miss is a data point, not a persistent cognitive pattern. Promote
      // it to the profile only after the same mechanism is observed again.
      if (observedPattern && observedPattern.occurrences >= 2) await updateCognitivePattern(attempt.type, observedPattern.label);
    }
  } catch(e) { console.error('savePracticeAttempt error:', e); }
}

