async function choosePathDiscuss() {
  document.getElementById('user-input').disabled = false;
  document.getElementById('send-btn').disabled = false;
  focusComposer();
  await startDiscussPath();
}

function choosePathPractice() {
  switchTab('practice');
}

async function startDiscussPath() {
  const profileHtml = '<div class="profile-card"><div class="label">Your Marg Profile</div><div class="profile-row"><div class="profile-item"><span>Attempt</span><span>' + studentProfile.attemptNumber + '</span></div><div class="profile-item"><span>Time left</span><span>' + studentProfile.monthsLeft + '</span></div><div class="profile-item"><span>Weak area</span><span>' + studentProfile.weakestSection + '</span></div><div class="profile-item"><span>Daily hours</span><span>' + studentProfile.dailyHours + '</span></div><div class="profile-item"><span>Situation</span><span>' + studentProfile.situation + '</span></div></div></div>';
  const firstMsg = buildPersonalizedOpening();
  setTimeout(function() {
    addMessage('marg', firstMsg + profileHtml, true);
    addSuggestionChips();
    const varcBtn = document.getElementById('varc-toggle-btn');
    if (varcBtn) varcBtn.style.display = 'inline-flex';
    const profileMsg = 'My profile: Attempt number: ' + studentProfile.attemptNumber + ', Months until CAT: ' + studentProfile.monthsLeft + ', Weakest section: ' + studentProfile.weakestSection + ', Daily study hours: ' + studentProfile.dailyHours + ', Current situation: ' + studentProfile.situation;
    conversationHistory.push({ role: 'user', content: profileMsg });
    conversationHistory.push({ role: 'assistant', content: firstMsg });
    saveChatMessage('user', profileMsg);
    saveChatMessage('assistant', firstMsg);
  }, 1000);
}

function buildPersonalizedOpening() {
  const attempt = studentProfile.attemptNumber;
  const months = studentProfile.monthsLeft;
  const weak = studentProfile.weakestSection;
  const hours = studentProfile.dailyHours;
  let opening = '';
  if (attempt === '1st attempt') { opening = "You're starting fresh, which means no bad habits to unlearn. That's an advantage most people don't realise."; }
  else if (attempt === '2nd attempt') { opening = "I've got your profile. Second attempt — you know what the exam feels like now. That experience is more valuable than you think. This time we go in with a real plan, not just hard work."; }
  else { opening = "Okay. I have your full picture. Multiple attempts mean you're serious about this — but it also means something specific hasn't been clicking. Let's find exactly what that is."; }
  opening += ' With <span class="highlight">' + months + '</span> left, studying <span class="highlight">' + hours + '/day</span>, and <span class="highlight">' + weak + '</span> as your weak spot — here\'s where we stand:';
  return opening;
}

function isLegacyStudentFacingFailureMessage(message) {
  if (!message || message.role === 'user') return false;
  var content = String(message.content || '');
  return /\b(?:draft|exercise|questions?|set|rc)\b.{0,90}\b(?:failed (?:its |the )?(?:completeness|answer|content)|did not (?:pass|finish|load)|discarded|independent answer check|generator is temporarily misconfigured)\b/i.test(content) ||
    /\b(?:completeness|answer) checks? pass\b/i.test(content) ||
    /\bMarg took too long to respond\b/i.test(content) ||
    /\bI could not verify that exact source confidently in this turn\b[\s\S]*?\buse Retry response\b/i.test(content) ||
    /\bMarg could not accept this request because its connection is misconfigured\b/i.test(content);
}

function getConversationMessageForDisplay(message) {
  if (!message) return null;
  if (message.role !== 'user') {
    // Older builds saved operational validation failures as if Marg had said
    // them to the student. They remain useful in incident memory, not in chat.
    if (isLegacyStudentFacingFailureMessage(message)) return null;
    return message;
  }
  var content = String(message.content || '');
  var legacyChoice = content.match(/In Marg(?:'|’)s 20-second check, I chose:\s*"([\s\S]*?)"\s*(?:\n|$)/i);
  if (!legacyChoice || content.indexOf('Treat this as a hypothesis') === -1) return message;
  var firstLine = content.split(/\n/)[0];
  var label = /\bDILR\b/i.test(firstLine) ? 'DILR'
    : /\bQA\b/i.test(firstLine) ? 'QA'
      : /\bRC\b|\bVARC\b/i.test(firstLine) ? 'RC'
        : /\bmock\b/i.test(firstLine) ? 'Mocks'
          : 'CAT preparation';
  return { role:'user', content:label + ' — ' + legacyChoice[1].trim() };
}

function renderInterruptedConversationRecovery(message) {
  if (!message || message.role !== 'user') return false;
  var container = document.getElementById('messages');
  if (!container || document.getElementById('interrupted-turn-recovery')) return false;
  var text = String(message.content || '').replace(/\n\[\d+ images attached[^\]]*\]$/i, '').trim();
  if (!text) return false;
  var card = document.createElement('div');
  card.id = 'interrupted-turn-recovery';
  card.className = 'fade-in';
  card.style.marginLeft = '38px';
  card.innerHTML = '<div class="onboard-card"><div style="font-size:13px;line-height:1.55;color:var(--text-muted);margin-bottom:10px">This message did not receive Marg’s answer. Continue it from the same point.</div><button type="button" class="pcard-nav-btn primary">Finish this answer</button></div>';
  card.querySelector('button').addEventListener('click', function() {
    var input = document.getElementById('user-input');
    if (!input || isLoading) return;
    lastFailedOutgoingMessage = { text:text, failedAt:Date.now(), requestId:'' };
    input.value = text;
    input.dispatchEvent(new Event('input', { bubbles:true }));
    card.remove();
    sendMessage();
  });
  container.appendChild(card);
  return true;
}

function restoreConversation() {
  onboardingComplete = true;
  recordEngagementEvent('onboarding_completed', { flow:'returning-user-backfill' }, 'onboarding-v1');
  showBottomNav();
  document.getElementById('user-input').disabled = false;
  document.getElementById('send-btn').disabled = false;
  // Remove legacy operational failure bubbles from the in-memory transcript as
  // well as the display. This lets a saved unanswered user turn be retried
  // without writing the same user message to Supabase a second time.
  conversationHistory = conversationHistory.filter(function(message) { return !isLegacyStudentFacingFailureMessage(message); });
  // conversationHistory is loaded directly from Supabase and no longer starts
  // with two synthetic system records. Slicing here hid the user's first real
  // homepage choice and Marg's first diagnosis after every refresh.
  const displayMessages = conversationHistory.filter(function(message) {
    // This sentence is navigation scaffolding, not conversation. Older versions
    // saved it to Supabase, so never replay those legacy rows after a refresh.
    if (isInternalMemoryMessage(message) || isLegacyAutoMissionReminder(message) || isHomeDiagnosisOpeningMessage(message)) return false;
    return true;
  }).map(getConversationMessageForDisplay).filter(function(message, index, list) {
    if (!message) return false;
    if (index === 0) return true;
    var previous = list[index - 1];
    return !(previous && previous.role === message.role && String(previous.content || '').replace(/\s+/g, ' ').trim() === String(message.content || '').replace(/\s+/g, ' ').trim());
  });
  if (displayMessages.length > 0) {
    var restoredArticleExercise = loadActiveGeneratedExercise();
    var restoredArticleWidget = false;
    isRestoringConversation = true;
    displayMessages.forEach(function(msg) {
      var isCurrentArticleRC = !restoredArticleWidget
        && msg.role !== 'user'
        && getArticleRCExerciseData(restoredArticleExercise)
        && String(msg.content || '').trim() === String(restoredArticleExercise.content.exerciseText || '').trim();
      if (isCurrentArticleRC) {
        activeGeneratedExercise = restoredArticleExercise;
        addArticleRCAttemptMessage(restoredArticleExercise);
        restoredArticleWidget = true;
        return;
      }
      const formatted = msg.role === 'user'
        ? escapeChatHtml(msg.content).replace(/\n\n/g, '<br><br>').replace(/\n/g, '<br>')
        : renderGroundingSourcesForChat(renderMentorStructuredText(msg.content));
      var restoredWrap = addMessage(msg.role === 'user' ? 'user' : 'marg', formatted);
      if (restoredWrap) {
        if (msg.id) restoredWrap.dataset.chatId = String(msg.id);
        restoredWrap.dataset.messageHash = simpleStableHash(msg.content || '');
        restoreResponseVersionsForBrowser(restoredWrap, msg);
      }
    });
    isRestoringConversation = false;
  }
  var lastRestoredMessage = displayMessages.length ? displayMessages[displayMessages.length - 1] : null;
  if (lastRestoredMessage && lastRestoredMessage.role === 'user') renderInterruptedConversationRecovery(lastRestoredMessage);
  if (displayMessages.length === 0) addSuggestionChips();
  scrollChatToLatest({ instant:true });
  restoreCurrentChatDraft();
  if (!scheduleHomepageIntentDispatch(250)) schedulePendingDeepLinkQuestionDispatch(250);
  focusComposer();
  var guidedRestored = restorePendingGuidedGeneration();
  restorePendingConversationalOptions();
  return guidedRestored;
}

function addSuggestionChips() {
  const container = document.getElementById('messages');
  const chipsDiv = document.createElement('div');
  chipsDiv.style.marginLeft = '38px'; chipsDiv.className = 'fade-in';
  const weak = studentProfile.weakestSection;
  let suggestions = ['Make my study plan', 'Which mock tests should I take?', 'How do I improve my accuracy?'];
  if (weak && weak.includes('VARC')) suggestions = ['How to improve VARC fast', 'RC strategy for beginners', 'Which mock tests should I take?'];
  if (weak && weak.includes('DILR')) suggestions = ['DILR sets practice strategy', 'How to attempt DILR in exam', 'Which mock tests should I take?'];
  if (weak && weak.includes('QA')) suggestions = ['QA topics to prioritise', 'How to build QA basics fast', 'Which mock tests should I take?'];
  chipsDiv.innerHTML = '<div class="chips">' + suggestions.map(function(s) { return '<button class="chip" onclick="sendQuick(\'' + s + '\')">' + s + '</button>'; }).join('') + '</div>';
  container.appendChild(chipsDiv);
  container.scrollTop = container.scrollHeight;
}

var typingStatusTimer = null;

function ensureMentorWorkIndicatorStyles() {
  if (document.getElementById('mentor-work-indicator-styles')) return;
  var style = document.createElement('style');
  style.id = 'mentor-work-indicator-styles';
  style.textContent = '.typing-bubble{min-width:min(280px,72vw);max-width:min(430px,78vw)}.mentor-work-indicator{display:flex;align-items:center;gap:10px;width:100%;min-width:210px}.typing-bubble .mentor-work-pulse{position:relative;display:block;width:18px;height:18px;flex:0 0 18px;border-radius:0;background:transparent;animation:none}.mentor-work-pulse:before,.mentor-work-pulse:after{content:"";position:absolute;inset:4px;border-radius:50%;background:var(--gold);animation:margWorkPulse 1.5s ease-out infinite}.mentor-work-pulse:after{animation-delay:.65s}.typing-bubble .mentor-work-copy{display:block;width:auto;height:auto;min-width:0;flex:1;border-radius:0;background:transparent;animation:none;font-size:12px;color:#aaa69e;line-height:1.35;white-space:normal;overflow-wrap:normal;word-break:normal;transition:opacity .18s ease,transform .18s ease}.mentor-work-copy.changing{opacity:.25;transform:translateY(2px)}@keyframes margWorkPulse{0%{transform:scale(.45);opacity:.9}80%,100%{transform:scale(1.6);opacity:0}}@media(max-width:480px){.typing-bubble{min-width:min(260px,76vw);max-width:76vw}.mentor-work-indicator{min-width:0}.typing-bubble .mentor-work-copy{font-size:11.5px}}';
  document.head.appendChild(style);
}

function buildMentorWorkStages(message, diagnosis, webGrounded) {
  var text = String(message || '').toLowerCase();
  if (webGrounded) return ['Checking the exact source', 'Comparing the current information', 'Writing a verified answer'];
  if (diagnosis && diagnosis.hasImage) return ['Reading the image carefully', 'Checking the visible values and conditions', 'Building the clearest response'];
  if (diagnosis && diagnosis.intent === 'answer_review') return ['Checking your choices', 'Tracing the exact decision error', 'Turning it into one reusable fix'];
  if ((diagnosis && (diagnosis.intent === 'planning' || diagnosis.comprehensivePlanning)) || /\b(?:plan|roadmap|timetable|schedule)\b/.test(text)) return ['Reading your actual constraints', 'Connecting them to your preparation', 'Building a plan you can follow'];
  if (/\b(?:mock|scorecard|sectional)\b/.test(text)) return ['Reading the result in context', 'Separating the score from the execution leak', 'Choosing the next useful check'];
  if (/\b(?:rc|varc|dilr|qa|quant|algebra|arithmetic)\b/.test(text)) return ['Reading the exact CAT problem', 'Checking it against your preparation pattern', 'Building the next useful move'];
  return ['Understanding what you mean', 'Connecting it to your context', 'Preparing the most useful response'];
}

function showTyping(message, diagnosis, webGrounded) {
  hideTyping();
  ensureMentorWorkIndicatorStyles();
  const container = document.getElementById('messages');
  if (!container) return;
  var stages = buildMentorWorkStages(message, diagnosis, webGrounded);
  const wrap = document.createElement('div');
  wrap.className = 'msg-wrap marg fade-in'; wrap.id = 'typing-wrap';
  wrap.innerHTML = '<div class="avatar"><img src="' + LOGO_ICON + '" alt="M"></div><div class="typing-bubble"><div class="mentor-work-indicator"><span class="mentor-work-pulse" aria-hidden="true"></span><span class="mentor-work-copy" role="status" aria-live="polite">' + escapeChatHtml(stages[0]) + '</span></div></div>';
  container.appendChild(wrap); container.scrollTop = container.scrollHeight;
  var stageIndex = 0;
  typingStatusTimer = setInterval(function() {
    var copy = document.querySelector('#typing-wrap .mentor-work-copy');
    if (!copy) { clearInterval(typingStatusTimer); typingStatusTimer = null; return; }
    stageIndex = Math.min(stageIndex + 1, stages.length - 1);
    copy.classList.add('changing');
    setTimeout(function() {
      var current = document.querySelector('#typing-wrap .mentor-work-copy');
      if (!current) return;
      current.textContent = stages[stageIndex];
      current.classList.remove('changing');
    }, 170);
    if (stageIndex === stages.length - 1) { clearInterval(typingStatusTimer); typingStatusTimer = null; }
  }, 1900);
}

function hideTyping() {
  if (typingStatusTimer) { clearInterval(typingStatusTimer); typingStatusTimer = null; }
  const el = document.getElementById('typing-wrap'); if (el) el.remove();
}

function buildActivitySummary() {
  if (!streakData || streakData.length === 0) return '';
  const today = new Date();
  const todayStr = formatDate(today);
  const checkedDates = new Set(streakData.map(function(c) { return c.date; }));
  let streak = calculateCurrentStreak(streakData);
  const weekDays = [];
  for (let i = 6; i >= 0; i--) { const day = new Date(); day.setDate(day.getDate() - i); weekDays.push(formatDate(day)); }
  const studiedThisWeek = weekDays.filter(function(d) { return checkedDates.has(d); }).length;
  const missedThisWeek = weekDays.filter(function(d) { return d < todayStr && !checkedDates.has(d); }).length;
  const weekAgo = new Date(); weekAgo.setDate(weekAgo.getDate() - 7);
  const weekStr = formatDate(weekAgo);
  const weeklyHours = streakData.filter(function(c) { return c.date >= weekStr; }).reduce(function(sum, c) { return sum + (c.hours || 0); }, 0);
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const yesterdayRecord = streakData.find(function(item) { return item.date === formatDate(yesterday); });
  let yesterdayActivity = 'no recorded activity';
  if (yesterdayRecord) {
    if (yesterdayRecord.studied === true && yesterdayRecord.hours > 0) yesterdayActivity = 'studied ' + yesterdayRecord.hours + ' hours';
    else if (yesterdayRecord.sources && yesterdayRecord.sources.indexOf('chat') !== -1) yesterdayActivity = 'used Marg and continued preparation';
    else if (yesterdayRecord.sources && yesterdayRecord.sources.indexOf('activity') !== -1) yesterdayActivity = 'returned to Marg';
    else if (yesterdayRecord.studied === false) yesterdayActivity = 'checked in without studying';
  }
  let summary = '\n\nSTUDENT ACTIVITY SUMMARY:';
  summary += '\n- Current streak: ' + streak + ' days';
  summary += '\n- This week: studied ' + studiedThisWeek + ' days, missed ' + missedThisWeek + ' days';
  summary += '\n- Hours this week: ' + weeklyHours.toFixed(1) + 'h';
  summary += '\n- Yesterday: ' + yesterdayActivity;
  if (missedThisWeek >= 3) summary += '\n- IMPORTANT: Tough week with consistency — address with empathy first.';
  if (streak >= 7) summary += '\n- IMPORTANT: ' + streak + ' day streak — acknowledge specifically.';
  return summary;
}

function sendQuick(text) {
  var input = document.getElementById('user-input');
  if (!input) return;
  if (!onboardingComplete && !conversationHistory.length) {
    showComposerStatus('Marg is still opening the conversation. Try this again once the first message appears.', 'info', true);
    return;
  }
  input.value = text;
  input.dispatchEvent(new Event('input'));
  sendMessage();
}

function timetableRoutineStorageKey() {
  return 'marg_timetable_routine_' + (currentUser && currentUser.id ? currentUser.id : 'guest');
}

function timetableAwaitingStorageKey() {
  return 'marg_timetable_awaiting_' + (currentUser && currentUser.id ? currentUser.id : 'guest');
}

function getSavedTimetableRoutine() {
  try { return localStorage.getItem(timetableRoutineStorageKey()) || ''; } catch(e) { return ''; }
}

function maybeHandleTimetableIntake(text) {
  var awaiting = false;
  try { awaiting = localStorage.getItem(timetableAwaitingStorageKey()) === '1'; } catch(e) {}
  if (awaiting) {
    try {
      localStorage.setItem(timetableRoutineStorageKey(), text);
      localStorage.removeItem(timetableAwaitingStorageKey());
    } catch(e) {}
    window._timetableRoutineJustCaptured = true;
    return false;
  }
  // A complete roadmap is broader than a timetable. Answer its phases,
  // sectionals and mocks first; routine details can be requested afterwards.
  if (isComprehensiveRoadmapRequest(text)) return false;
  // Let the mentor resolve one-day versus rotation ambiguity before collecting
  // routine details or generating a timetable from the wrong interpretation.
  if (isPlanSequenceAmbiguous(text)) return false;
  if (!/\b(timetable|daily schedule|study schedule|plan my day|build.*study plan)\b/i.test(text) || getSavedTimetableRoutine()) return false;
  try { localStorage.setItem(timetableAwaitingStorageKey(), '1'); } catch(e) {}
  addMentorLeadMessage("I can definitely do that. If you're comfortable sharing your daily routine, I'll build it around your actual schedule. In one line, tell me your fixed commitments, earliest realistic start, latest finish, and how much CAT time you can genuinely protect.");
  return true;
}

async function maybeStartSavedDiagnosticCheck(text) {
  if (!/\b(start|begin|do|launch)\b.*\b(check|exercise|set)\b|\bstart the check\b/i.test(text)) return false;
  loadPendingDiagnosticExercise();
  if (!pendingDiagnosticExercise || !pendingDiagnosticExercise.entry) return false;
  var entry = pendingDiagnosticExercise.entry;
  if (entry.topic === 'dilr') {
    addMentorLeadMessage(getDILROpeningLesson(entry));
    savePendingDiagnosticExercise(entry, 'ready_after_lesson');
    showConversationalOptions(['Start the set'], 'start_dilr_validation');
  } else {
    savePendingDiagnosticExercise(entry, 'generating');
    var generated = await runPredictionValidationExercise(entry);
    if (generated !== false) savePendingDiagnosticExercise(null);
    else savePendingDiagnosticExercise(entry, 'retry');
  }
  return true;
}

var pendingSectionalRecommendation = null;

function isPracticeProductQuestion(text) {
  var value = String(text || '').trim();
  if (!value) return false;
  // A pasted worksheet/passsage can contain incidental words such as
  // "practice", "same" and several question marks. Those words describe the
  // material; they are not a question about Marg's Practice product. Keep
  // answer-bearing assessment submissions on the normal review path.
  var answerLabels = (value.match(/\b(?:my\s+answer|answer)\s*:/gi) || []).length;
  var numberedQuestions = (value.match(/(?:^|\n)\s*(?:q(?:uestion)?\s*)?\d+[.)]?\s+/gi) || []).length;
  if (value.length > 600 && (answerLabels >= 1 || numberedQuestions >= 3)) return false;
  // Product-bank questions must explicitly ask about availability, freshness or
  // repetition. A previous broad keyword rule intercepted ordinary mentoring
  // sentences such as “these are three different problems” merely because the
  // word “problems” looked like “questions”.
  // Do not treat the bare word "practice" as product intent: normal RC prose
  // frequently uses it as a noun or verb (for example, "the practice of
  // borrowing"). Require a recognisable Marg surface or exercise type.
  var explicitMaterial = /\b(?:practice|practise)\s+(?:tab|section|questions?|sets?|exercises?|material|content)\b|\b(?:question|set)\s+bank\b|\b(?:rc|varc)\s+(?:passages?|questions?|sets?)\b|\b(?:dilr|lrdi)\s+(?:practice|sets?|questions?)\b|\b(?:qa|quant|quants)\s+(?:practice|questions?|sets?)\b|\bsectional\s+tests?\b/i.test(value);
  if (!explicitMaterial) return false;
  var availabilityQuestion = /\b(?:how many|limited|limit|available|availability|question bank|set bank|do you have|will i get)\b/i.test(value);
  var repeatQuestion = /\b(?:same|repeat(?:ed|ing|s)?|unique|fresh|new each time|different each time)\b/i.test(value) &&
    /(?:\?|\b(?:is|are|does|do|can|will|why|would)\b)/i.test(value);
  return availabilityQuestion || repeatQuestion;
}

function maybeHandlePracticeProductQuestion(text) {
  if (!isPracticeProductQuestion(text)) return false;
  var value = String(text || '');
  var section = /\b(?:dilr|lrdi)\b/i.test(value) ? 'DILR' : /\b(?:rc|varc)\b/i.test(value) ? 'RC' : /\b(?:qa|quant|quants)\b/i.test(value) ? 'QA' : '';
  var repeated = /\b(?:repeat(?:ed|ing|s)?|same)\b/i.test(value);
  var reply = (section ? section + ' practice' : 'Practice') + ' uses checked exercises and tries to rotate what you see.';
  if (repeated) reply += ' If a topic-matched exercise repeats, Marg will label it clearly and you can switch to another set from the same section.';
  else reply += ' Choose the section and topic you want; if that exact combination is unavailable, Marg will offer a ready set from the same section instead of stopping your session.';
  addMentorLeadMessage(reply);
  return true;
}

function maybeLeadWithProgression(text) {
  if (isComprehensiveRoadmapRequest(text)) return false;
  // Questions about how Practice itself works need a direct factual answer.
  // A broad keyword match used to hijack "are DILR sets repeated?" and show a
  // sectional recommendation four times instead of answering it.
  if (isPracticeProductQuestion(text) || isExactExerciseReplayRequest(text) || isAnswerReviewRequest(text)) return false;
  if (!/\b(qa|quant|dilr|questions?|practice|worksheet|sectional)\b/i.test(text)) return false;
  var recommendation = bestSectionalRecommendation();
  if (!recommendation) return false;
  var mentionsSection = new RegExp('\\b' + (recommendation.section === 'qa' ? '(qa|quant|quants)' : '(dilr|lrdi)') + '\\b', 'i').test(text);
  var mentionsTopic = String(text).toLowerCase().indexOf(String(recommendation.topic).toLowerCase()) !== -1;
  if (!mentionsSection && !mentionsTopic) return false;
  pendingSectionalRecommendation = recommendation;
  addMentorLeadMessage("You've already completed " + recommendation.conceptQuestionsCompleted + ' ' + recommendation.topic + " questions. Another worksheet will not tell us much now. I think it is time to pressure-test the topic with a timed sectional. When do you want to do it?");
  showConversationalOptions(['Right now', 'Later today', 'Tomorrow'], 'topic_sectional_timing');
  return true;
}

async function handleTopicSectionalTiming(answer) {
  var item = pendingSectionalRecommendation || bestSectionalRecommendation();
  if (!item) return;
  var normalized = String(answer || '').toLowerCase();
  if (/right now|now/.test(normalized)) {
    item.sectionalSuggested = true;
    saveTopicProgression();
    startTimedTest(item.section, item.topic, item.section === 'qa' ? 10 : 12);
    return;
  }
  item.sectionalSuggested = true;
  item.scheduledSectional = /tomorrow/.test(normalized) ? 'tomorrow' : 'later_today';
  saveTopicProgression();
  addMentorLeadMessage(item.scheduledSectional === 'tomorrow'
    ? 'Done. Tomorrow, I’ll bring you back to the ' + item.topic + ' timed sectional—not another worksheet.'
    : 'Done. Later today, I’ll keep the ' + item.topic + ' timed sectional as the next move.');
  await scheduleMentorPushReminder(
    item.scheduledSectional === 'tomorrow' ? 'tomorrow' : 'later_today',
    item.section === 'qa' ? 'qa' : 'sectional',
    { source:'progression-chat', kind:item.section === 'qa' ? 'qa' : 'sectional', topic:item.topic, task:'the ' + item.topic + ' timed sectional', action:'Run the pressure test Marg recommended instead of opening another worksheet.' }
  );
}

function isDataDeletionRequest(message) {
  return /\b(?:delete|erase|remove|wipe|forget)\b[\s\S]{0,35}\b(?:my\s+)?(?:data|account|profile|history|chats?|information|records?|memory|everything\s+(?:about|on)\s+me)\b/i.test(String(message || ''));
}

function buildPrivacyRequestReply(message) {
  if (isDataDeletionRequest(message)) {
    return 'Marg does retain data across sessions. For signed-in users, this can include conversation history, study profile, diagnoses, assigned mentor tasks, attempts and evidence reviews, cognitive and behavioural patterns, mock history, practice progress, check-ins, engagement milestones, and browser-push subscription and delivery records. A community invite phone number is stored only if you submit it. Some drafts and task state are also stored in your browser.\n\nClearing this chat or browser storage does not delete the Supabase records. To request deletion of your account and associated data, email support@trymarg.com from the email linked to your Marg account. The published processing time is within 7 business days.';
  }
  return 'Marg is not session-only. Signed-in conversation history, study profile, diagnoses, assigned tasks, attempts and evidence reviews, cognitive and behavioural patterns, mock history, practice progress, check-ins, engagement milestones, and browser-push subscription and delivery records can persist in Supabase across sessions. A community invite phone number is stored only if you choose to submit it. Some drafts and task state are also stored in your browser, and submitted chat content may be processed through Gemini to generate replies.\n\nFor deletion or a privacy request, email support@trymarg.com from your account email. Clearing local storage alone does not remove Supabase records.';
}

function maybeHandlePrivacyRequest(message) {
  if (!isDataPrivacyRequest(message)) return false;
  var reply = buildPrivacyRequestReply(message);
  addMessage('marg', escapeChatHtml(reply).replace(/\n\n/g, '<br><br>').replace(/\n/g, '<br>'));
  conversationHistory.push({ role:'assistant', content:reply });
  if (!isGuestMode) saveChatMessage('assistant', reply);
  return true;
}

function ambiguousShortInputClarification(message) {
  var original = String(message || '').trim();
  var normalized = original.toLowerCase().replace(/[^a-z]/g, '');
  if (!normalized || original.split(/\s+/).length !== 1 || normalized.length > 18) return '';
  if (/^[a-d]$/.test(normalized)) return '';
  var known = new Set([
    'hi','hey','hello','help','bro','bhai','yes','no','yep','nope','ok','okay','exactly','mostly','continue',
    'varc','dilr','lrdi','qa','rc','mock','mocks','strategy','confidence','algebra','arithmetic','geometry',
    'log','logs','logarithm','logarithms','quadratic','quadratics','linear','tsd','pj','pjs','parajumble','parajumbles',
    'tita','lod','lod1','lod2','numbersystem','sentenceplacement','oddoneout','aeon','hindu',
    'percentage','percentages','busy','tired','exhausted','stuck','confused','anxious','now','later','today','tomorrow',
    'time','ims','aimcat','aimcats','simcat','simcats','cracku','cl','careerlauncher','catking','rodha'
  ]);
  if (known.has(normalized) || normalized.length < 3) return '';
  if (['bosy','bisy','bussy','buzy'].indexOf(normalized) !== -1) return 'Did you mean busy, or something else? What’s going on?';
  return 'I may be reading “' + original.slice(0, 24) + '” wrong. What did you mean?';
}

function maybeHandleAmbiguousShortInput(message) {
  var reply = ambiguousShortInputClarification(message);
  if (!reply) return false;
  addMessage('marg', escapeChatHtml(reply));
  conversationHistory.push({ role:'assistant', content:reply });
  if (!isGuestMode) saveChatMessage('assistant', reply);
  return true;
}

function parseExplicitPracticeLaunchRequest(message) {
  var text = String(message || '').trim();
  var rejectsLaunch = /\b(?:don['’]?t|do not|no need to|not ready to)\s+(?:(?:please|just|yet|now|currently)\s+){0,3}(?:give|show|send|generate|create|start|open|launch|practi[cs]e)\b/i.test(text) ||
    /\b(?:don['’]?t|do not)\s+want\s+(?:(?:you|marg)\s+)?to\s+(?:give|show|send|generate|create|start|open|launch|practi[cs]e)\b/i.test(text) ||
    /\bwithout\s+(?:you\s+)?(?:giving|showing|sending|generating|creating|starting|opening|launching)\b/i.test(text);
  if (rejectsLaunch) return null;
  if (/\b(?:solutions?|answers?|explanations?)\s+(?:to|for|of)\s+(?:this|these|the|my|that|above|previous|same|all)\b|\b(?:check|review|explain|solve)\s+(?:this|these|my|that|above|previous|same)\b/i.test(text)) return null;
  if (/\b(?:how (?:do|should|can) i|explain how to|tell me how to|i (?:do not|don['’]?t) know how to)\s+(?:start|open|approach|attempt)\b/i.test(text)) return null;
  // Advice, diagnosis and planning belong in chat even when the sentence also
  // contains a section name and a broad verb such as "give" or "start".
  if (/\b(?:advice|guidance|feedback|plan|roadmap|reason|explanation|strategy|approach|diagnos(?:e|is|tic)|discussion|talk|help|understand)\b|\b(?:one thing|what)\s+to\s+change\b|\btell me whether\b/i.test(text) &&
      !/\b(?:generate|create|launch|start)\b[\s\S]{0,35}\b(?:questions?|passage|practice|practise|test|set)\b/i.test(text)) return null;
  var strongAction = /\b(?:generate|create|launch)\b[\s\S]{0,55}\b(?:questions?|practice|practise|passage|rc|dilr|lrdi|qa|quant|quants|test|set)\b/i.test(text) ||
    /\b(?:start|open)\s+(?:(?:a|an|the|one|another|new|fresh|full|short|timed|cat[ -]style)\s+){0,4}(?:practice|practise|passage|rc|varc|dilr|lrdi|qa|quant|quants|test|set|questions?)\b/i.test(text) ||
    /\b(?:let['’]?s do|i want to (?:do|practi[cs]e)|can we do)\b[\s\S]{0,45}\b(?:questions?|practice|practise|passage|rc|dilr|lrdi|qa|quant|quants|test|set)\b/i.test(text);
  var directGive = /\b(?:give|show|send)\s+me\b[\s\S]{0,70}\b(?:questions?|practice|practise|passage|rc|dilr|lrdi|qa|quant|quants|test|set)\b/i.test(text);
  var action = strongAction || directGive;
  var material = /\b(?:questions?|practice|practise|passage|rc|varc|dilr|lrdi|qa|quant|quants|sectional|test|set)\b/i.test(text);
  if (!action || !material) return null;
  // One conversational follow-up on an already visible passage belongs in
  // chat. Multi-question/new-session requests belong in the verified widget.
  if (/\b(?:one more|another)\s+question\b/i.test(text) && /\b(?:this|same)\s+passage\b/i.test(text)) return null;

  var type = /\b(?:dilr|lrdi|logical reasoning|data interpretation)\b/i.test(text) ? 'dilr'
    : /\b(?:rc|varc|reading comprehension|(?:fresh|new|another|full|short|single|one)\s+(?:CAT[ -](?:style|length)\s+)?passage|passage check|varc passage)\b/i.test(text) ? 'rc'
    : /\b(?:qa|quant|quants|percentages?|ratio|proportion|profit|loss|time[ -]speed|quadratic|linear equation|algebra|geometry|mensuration|logarithm|number system|probability|permutation|combination)\b/i.test(text) ? 'qa'
    : null;
  if (!type) return null;

  var topics = [
    ['Arithmetic', /\barithmetic\b/i], ['Algebra', /\balgebra\b/i],
    ['Geometry', /\bgeometry\b/i], ['Modern Math', /\bmodern math\b/i],
    ['Percentages', /\bpercentages?\b/i], ['Ratios & Proportions', /\b(?:ratios?|proportions?)\b/i],
    ['Time-Speed-Distance', /\b(?:time[ -]speed[ -]distance|tsd)\b/i], ['Profit & Loss', /\bprofit\b|\bloss\b/i],
    ['Linear Equations', /\blinear equations?\b/i], ['Quadratic Equations', /\bquadratic(?: equations?)?\b/i],
    ['Functions & Inequalities', /\b(?:functions?|inequalities?)\b/i], ['Logarithms & Exponents', /\b(?:logarithms?|logs?|exponents?|indices)\b/i],
    ['Geometry (Triangles, Circles)', /\b(?:geometry|triangles?|circles?)\b/i], ['Mensuration (2D & 3D)', /\bmensuration\b/i],
    ['Number Systems', /\bnumber systems?\b/i], ['Permutation & Combination', /\b(?:permutation|combination|p\s*&\s*c)\b/i],
    ['Probability', /\bprobability\b/i], ['Set Theory', /\bset theory\b/i]
  ];
  var topic = null;
  if (type === 'qa') {
    topics.some(function(item) { if (item[1].test(text)) { topic = item[0]; return true; } return false; });
  } else if (type === 'dilr') topic = getVerifiedDILRTopicFromRequest(text);
  var timed = /\b(?:timed|sectional)\b/i.test(text);
  var requestedCountMatch = text.match(/\b(\d{1,2})\s*(?:-\s*)?(?:question|set)s?\b/i);
  var requestedCount = requestedCountMatch ? Number(requestedCountMatch[1]) : 0;
  if (type === 'qa' && (requestedCount < 3 || requestedCount > 10)) requestedCount = 0;
  if (type === 'dilr' && [4, 8, 12].indexOf(requestedCount) === -1) requestedCount = 0;
  return { type:type, topic:topic, timed:timed, requestedCount:requestedCount };
}

async function maybeGenerateConversationalRC(message) {
  var request = parseExplicitPracticeLaunchRequest(message);
  var latestAssistant = (conversationHistory || []).slice().reverse().find(function(item) { return item && item.role === 'assistant' && !/^\[MARG_INTERNAL:/.test(item.content || ''); });
  var previous = String(latestAssistant && latestAssistant.content || '');
  var acceptsPassage = /^(?:yes(?: sure)?|yep|sure|okay|ok|let['’]?s do it|go ahead)[.!\s]*$/i.test(String(message || '').trim()) && /\b(?:want|shall|ready|would you like)\b[^?\n]{0,160}\b(?:fresh|new|another|full|short|one)[^?\n]{0,50}\b(?:passage|RC)\b/i.test(previous);
  var missingControl = /\b(?:don['’]?t|do not|can['’]?t|cannot)\s+(?:see|find)\b[^.!?\n]{0,45}\b(?:start|button|check)\b/i.test(String(message || '')) && /\b(?:passage|RC|reading)\b/i.test(previous);
  if (acceptsPassage || missingControl) request = {type:'rc',topic:null};
  if (!request || request.type !== 'rc' || request.timed || /\b(?:practice|practise)\s+(?:tab|section|page)\b/i.test(String(message || ''))) return false;
  // Reuse the existing checked, four-question RC card inside this thread.
  // A conversational request must not silently navigate away from the chat.
  if (!articleRCGenerating) {
    currentArticle = selectCuratedRCTheme(currentTopic, Math.max(0, Number(articleIndex) || 0));
    await createRCPassage();
  }
  return true;
}

function maybeLaunchExplicitPracticeRequest(message) {
  var request = parseExplicitPracticeLaunchRequest(message);
  if (!request) return false;
  var explicitlyOpenedPracticePage = /\b(?:open|go to|take me to|show)\b[\s\S]{0,35}\bpractice\s+(?:tab|page|section)\b/i.test(String(message || ''));
  if (explicitlyOpenedPracticePage) {
    currentPracticeType = request.type;
    currentSetIndex = 0;
    currentQuestionIndex = 0;
    practiceAnswered = false;
    practiceTopicChosen = request.type === 'rc' || !!request.topic;
    selectedPracticeTopic = request.topic || null;
    document.querySelectorAll('.ptab-btn').forEach(function(button) { button.classList.remove('active'); });
    var requestedTabButton = document.getElementById('ptab-' + request.type);
    if (requestedTabButton) requestedTabButton.classList.add('active');
    switchTab('practice');
    return true;
  }
  // “Timed” and “sectional” are execution instructions, not merely Practice
  // discovery terms. Honour the section and topic already supplied instead of
  // navigating to a second picker that makes the student repeat the request.
  if (request.timed) {
    if (request.type === 'rc') {
      startSectionalFromHub('varc');
      return true;
    }
    var timedTopic = request.topic || (request.type === 'qa' ? 'Mixed QA' : 'Mixed Set Selection');
    var timedCount = request.requestedCount || (request.type === 'qa' ? 10 : 12);
    startTimedTest(request.type, timedTopic, timedCount, null, 0);
    return true;
  }
  // Ordinary “practise QA/DILR” requests stay anchored to the current chat.
  // Open a compact checked exercise in the overlay instead of silently
  // moving the user to the Practice page and losing the conversation thread.
  if (request.type === 'qa' || request.type === 'dilr') {
    switchTab('chat');
    var chatTopic = request.topic || (request.type === 'qa' ? 'Mixed QA' : 'Mixed Set Selection');
    var chatCount = request.requestedCount || (request.type === 'qa' ? 3 : 4);
    startTimedTest(request.type, chatTopic, chatCount, null, 0);
    return true;
  }
  return true;
}

function maybeHandleSectionChoicePrompt(message) {
  var text = String(message || '').trim();
  var match = text.match(/^(?:let'?s\s+)?(?:unpack|compare|look at|do|pick)\s+(VARC|DILR|QA)\s+or\s+(VARC|DILR|QA)(?:\s+first)?[?.!]*$/i);
  if (!match) return false;
  var first = match[1].toUpperCase();
  var second = match[2].toUpperCase();
  addMentorLeadMessage('Which one should we open first?');
  showConversationalOptions([first, second], 'mock_section_priority');
  return true;
}

function maybeHandleStopSummary(message) {
  if (!/^(?:stop|enough|bas)[.!\s]*(?:[\s\S]*\b(?:one|1|single)[ -]point\b[\s\S]*\bsummary\b|[\s\S]*\bsummary\b[\s\S]*\b(?:one|1|single)[ -]point\b)/i.test(String(message || '').trim())) return false;
  var recentUsers = conversationHistory.filter(function(turn) { return turn.role === 'user' && turn.content !== message; }).slice(-3).map(function(turn) { return String(turn.content || ''); }).join(' ');
  var point = '';
  if (/\b(?:claims?|references?|find (?:the )?line|function[ -]mapping|paragraph (?:role|function))\b/i.test(recentUsers)) {
    point = 'Use each paragraph’s role to locate the claim, then check that exact part of the passage before comparing options. Reading smoothly alone doesn’t tell us whether that step is working.';
  } else {
    for (var i = conversationHistory.length - 1; i >= 0; i--) {
      if (conversationHistory[i].role !== 'assistant') continue;
      var previous = String(conversationHistory[i].content || '').replace(/\[[^\]]*\]/g, '').replace(/[#*]/g, '').trim();
      var sentence = previous.match(/[^.!?\n]{20,280}[.!]/);
      if (sentence) point = sentence[0].trim();
      break;
    }
  }
  addMentorLeadMessage(point || 'Stay with the specific difficulty we discussed; we haven’t gathered enough evidence to label your overall ability.');
  return true;
}

function maybeHandleCatDurationQuestion(message) {
  var text = String(message || '');
  if (!/\bCAT\b/i.test(text)) return false;
  if (/\b(?:how many|how long)[^.!?\n]{0,65}\b(?:study|studying|prepare|preparation|practi[cs]e)\b/i.test(text)) return false;
  // Hours available for studying and minutes spent on a set are not questions
  // about the exam's duration. Never intercept a student's mock story.
  var asksDuration = /\b(?:how (?:long|many (?:hours?|minutes?))|what(?:'s| is) (?:the )?(?:total )?duration)\b[\s\S]{0,55}\b(?:CAT|exam|paper|mock|test)\b|\b(?:CAT|exam|paper|mock|test)\b[\s\S]{0,40}\b(?:duration|how long|how many (?:hours?|minutes?))\b|\b(?:is|does)\s+(?:the\s+)?CAT\b[\s\S]{0,35}\b(?:\d+|two|three)\s*[- ]?hours?\b/i.test(text);
  if (!asksDuration || text.length > 240 && /\b(?:scored?|VARC|DILR|QA|study|studying|after work)\b/i.test(text)) return false;
  var asksPwd = /\b(?:PwD|PWD|person with disabilit|disability)\b/i.test(text);
  var reply = asksPwd
    ? 'For CAT 2025, PwD candidates had 160 minutes in total: 53 minutes 20 seconds per section. For CAT 2026, use the current official notification once it is released because accommodation rules must not be guessed.'
    : 'A standard CAT-pattern full mock is 2 hours: 40 minutes each for VARC, DILR and QA. It is not a 3-hour paper.';
  addMentorLeadMessage(reply);
  return true;
}

var activeMockReviewPriority = '';
var activeMockReviewSource = '';

function isMultiSectionMockNarrative(message) {
  var text = String(message || '').toLowerCase();
  // Mentioning several scores inside a correction, recall or answer-review
  // request is not consent to restart diagnosis. The newest task wins.
  if (/\b(?:correction|corrected|remember|recall|summari[sz]e|you (?:said|ignored|invented)|don['’]?t restart|do not restart|which (?:of (?:those|these) )?answers?\b|which answers? were|what (?:were|are) my)\b/.test(text)) return false;
  if (/\bQ(?:uestion)?\s*\d+\s*[:.)-]/i.test(String(message || ''))) return false;
  if (!/\b(?:mock|aimcat|simcat|scorecard|sectional scores?)\b/.test(text)) return false;
  var sectionCount = [
    /\b(?:varc|rc|reading comprehension|verbal ability)\b/,
    /\b(?:dilr|lrdi|data interpretation|logical reasoning)\b/,
    /\b(?:qa|quant|quants|quantitative aptitude)\b/
  ].filter(function(pattern) { return pattern.test(text); }).length;
  return sectionCount >= 2 && text.split(/\s+/).length >= 45;
}

function getPriorStudentSectionEvidence(currentMessage) {
  var items = Array.isArray(conversationHistory) ? conversationHistory.slice() : [];
  var skippedCurrent = false;
  var current = String(currentMessage || '').trim();
  var userTurns = [];
  for (var i = items.length - 1; i >= 0; i--) {
    var item = items[i];
    if (!item || item.role !== 'user' || isInternalMemoryMessage(item)) continue;
    var content = String(item.content || '').trim();
    if (!skippedCurrent && content === current) { skippedCurrent = true; continue; }
    if (content && !isSimpleGreeting(content)) userTurns.unshift(content);
  }
  var evidence = { varc:false, dilr:false, qa:false };
  userTurns.forEach(function(turn) {
    // Section scores alone say where marks fell, not what was discussed about
    // the student's process. Count only a student-described decision, method,
    // mistake or difficulty as prior section evidence.
    if (/\b(?:RC|VARC|passage|para\s*jumbles?|sentence\s*placement)\b[\s\S]{0,140}\b(?:option|claim|reference|tone|purpose|read|reread|understand|locate|rush|slow|wrong|confus|time)\b|\b(?:option|claim|reference|tone|purpose|read|reread|understand|locate|rush|slow|wrong|confus|time)\b[\s\S]{0,140}\b(?:RC|VARC|passage)\b/i.test(turn)) evidence.varc = true;
    if (/\b(?:DILR|LRDI|DI\s*LR|set)\b[\s\S]{0,140}\b(?:select|selection|grid|table|case|constraint|clue|deduction|arrangement|leave|exit|stuck|minutes?|time)\b|\b(?:select|selection|grid|table|case|constraint|clue|deduction|arrangement|leave|exit|stuck|minutes?|time)\b[\s\S]{0,140}\b(?:DILR|LRDI|set)\b/i.test(turn)) evidence.dilr = true;
    if (/\b(?:QA|quant|arithmetic|algebra|geometry|number systems?|modern math|LCM|HCF|equation|formula)\b[\s\S]{0,160}\b(?:method|recogn|recall|forget|forgot|solve|setup|attempt|correct|wrong|slow|stuck|overthink|time)\b|\b(?:method|recogn|recall|forget|forgot|solve|setup|attempt|correct|wrong|slow|stuck|overthink|time)\b[\s\S]{0,160}\b(?:QA|quant|arithmetic|algebra|geometry|number systems?|LCM|HCF|equation|formula)\b/i.test(turn)) evidence.qa = true;
  });
  ['varc','dilr','qa'].forEach(function(section) {
    var diagnosis = typeof diagnosticMemory !== 'undefined' && diagnosticMemory && diagnosticMemory[section];
    if (diagnosis && (diagnosis.status === 'supported' || diagnosis.status === 'confirmed') && !diagnosis.doNotReuse) evidence[section] = true;
  });
  return Object.keys(evidence).filter(function(section) { return evidence[section]; });
}

function getMultiSectionConversationGuidance(message, diagnosis) {
  if (!diagnosis || diagnosis.intent !== 'mock_diagnosis' || !isMultiSectionMockNarrative(message)) return '';
  var discussed = getPriorStudentSectionEvidence(message);
  if (discussed.length) {
    return '\nCONTINUING MULTI-SECTION CHAT: The student has already described real process evidence for ' + discussed.map(function(section) { return section.toUpperCase(); }).join(', ') + '. Answer the newest question from that evidence and give one immediately usable change—not only a problem label. Do not restart mock intake, do not ask which section to unpack, and do not repeat a generic section-choice script. If another section genuinely lacks evidence, leave it unlabelled rather than discarding the answer the student asked for.';
  }
  return '\nFIRST BROAD MOCK TURN: No section-level process has been discussed before this message. First answer every direct question and respond to the personal pressure or uncertainty actually expressed. Do not replace that answer with an intake prompt. Only after giving useful value, ask which section to examine first and append [OPTIONS: VARC|DILR|QA][CONTEXT: mock_section_priority]. Never use a fixed “scores tell us where the marks went” script.';
}

function askMockSectionEvidenceQuestion(section) {
  activeMockReviewPriority = String(section || '').toLowerCase();
  if (activeMockReviewPriority === 'dilr') {
    addMentorLeadMessage(activeMockReviewSource === 'scores'
      ? 'Think about the DILR set that consumed the most time. Near the end, what was happening?'
      : 'In the DILR set you stayed with, what kept you there near the end?');
    showConversationalOptions(['I was still finding useful deductions', 'I was trying cases without real progress', 'A bit of both'], 'mock_section_evidence');
    return;
  }
  if (activeMockReviewPriority === 'varc') {
    addMentorLeadMessage(activeMockReviewSource === 'scores'
      ? 'Thinking about VARC, where did the marks mostly slip?'
      : 'Thinking about VARC, where did the marks mostly slip?');
    showConversationalOptions(['I misunderstood the passage', 'I got stuck between two options', 'I ran out of time near the end'], 'mock_section_evidence');
    return;
  }
  addMentorLeadMessage(activeMockReviewSource === 'scores'
    ? 'For the QA questions you left or got wrong, what happened most often?'
    : 'For the QA questions you left or got wrong, what happened most often?');
  showConversationalOptions(['I could not spot the method', 'I knew the method but was too slow', 'I made mistakes after the setup'], 'mock_section_evidence');
}

// --- Study session: material the student supplied in this conversation -------
function adoptStudyMaterial(turn) {
  if (!ensureStudyConfigured() || !turn || !turn.analysis) return null;
  var ctx = MargStudy.setContext(turn.analysis, turn.analysis.body);
  // Pasted study material replaces any half-finished external-question intake.
  if (pendingExternalQuestion) savePendingExternalQuestion(null);
  pendingExternalQuestionTurnMode = '';
  return ctx;
}

function recordStudyStudentStep(turn, text) {
  if (!ensureStudyConfigured() || !turn) return;
  var label = turn.type === 'material' ? 'material' : turn.label || turn.type;
  var body = turn.type === 'material' && turn.analysis ? (turn.analysis.instruction || 'Shared the material.') : text;
  MargStudy.recordStep('student', label, body);
}

function recordStudyMentorStep(turn, reply) {
  if (!ensureStudyConfigured() || !turn) return;
  var summary = String(reply || '').replace(/\s+/g, ' ').trim().slice(0, 360);
  MargStudy.recordStep('marg', turn.label || turn.type, summary);
  var ctx = MargStudy.getContext();
  if (!ctx || turn.type !== 'analysis_step') return;
  var done = Array.isArray(ctx.claimsDone) ? ctx.claimsDone.slice() : [];
  if (turn.label && done.indexOf(turn.label) === -1) done.push(turn.label);
  var labels = (ctx.passages || []).map(function(item) { return item.label; });
  var allDone = labels.length > 0 && labels.every(function(label) { return done.indexOf(label) !== -1; });
  var patch = { claimsDone: done };
  if (allDone) patch.pendingTask = ctx.framing && ctx.framing.questionsLater ? 'questions' : '';
  MargStudy.updateContext(patch);
}

function trimDanglingStudyText(text) {
  var value = String(text || '').replace(/\s+$/, '');
  if (!MargStudy.looksCutOff(value)) return value;
  var cut = value.lastIndexOf('\n\n');
  return cut > value.length * 0.4 ? value.slice(0, cut).trim() : value;
}

// A reply that ends on the token ceiling is unfinished, not final. Resume it
// from its exact endpoint instead of asking the student to type "continue" or
// replacing it with a local fallback.
async function resolveStudyReply(payload, request, timeoutMs, options) {
  options = options || {};
  var truncated = isGeminiStructuredResponseTruncated(payload);
  var text = '';
  try { text = getGeminiText(payload); } catch (error) { if (!truncated) throw error; }
  if (!truncated) return text;
  async function call(body) {
    var response = await fetchWithTimeout(WORKER_URL, { method:'POST', headers:{ 'Content-Type':'application/json' }, body:JSON.stringify(body) }, timeoutMs);
    return response.json();
  }
  function leanCopy() {
    var copy = JSON.parse(JSON.stringify(request));
    copy.generationConfig = copy.generationConfig || {};
    copy.generationConfig.thinkingConfig = { thinkingLevel:'minimal' };
    return copy;
  }
  if (!text) {
    var retry = await call(leanCopy());
    truncated = isGeminiStructuredResponseTruncated(retry);
    text = getGeminiText(retry);
  }
  for (var round = 0; truncated && round < 3; round++) {
    var next = leanCopy();
    next.contents = next.contents.concat([
      { role:'model', parts:[{ text:text }] },
      { role:'user', parts:[{ text:MargStudy.buildContinuationPrompt(text) }] }
    ]);
    var payloadNext = await call(next);
    truncated = isGeminiStructuredResponseTruncated(payloadNext);
    var chunk = '';
    try { chunk = getGeminiText(payloadNext); } catch (error) { break; }
    text = MargStudy.stitchContinuation(text, chunk);
  }
  if (!truncated) return text;
  // Study chat used to keep a trimmed fragment and ordinary chat used to drop
  // it. Keep the visible text in both cases, and say that it stopped.
  var partial = String(trimDanglingStudyText(text) || '').trim();
  if (partial) return partial + '\n\nThis reply stopped before it was finished. Say continue and I will pick up from this point.';
  var unfinished = new Error('Mentor output hit the token ceiling');
  unfinished.name = 'GeminiEmptyResponseError';
  throw unfinished;
}

function getStudyQuestionSchema(count) {
  return {
    type:'object', required:['questions'],
    properties:{ questions:{ type:'array', minItems:count, maxItems:count, items:{
      type:'object',
      required:['passage','q','options','correct','explanation','trap_type','sufficiency_check','option_check'],
      properties:{
        passage:{ type:'string' }, q:{ type:'string' },
        options:{ type:'array', minItems:4, maxItems:4, items:{ type:'string' } },
        correct:{ type:'integer', minimum:0, maximum:3 },
        explanation:{ type:'string' }, trap_type:{ type:'string' },
        sufficiency_check:{ type:'string', description:'A full evidence sentence from the material, at least 40 characters.' },
        option_check:{ type:'string', description:'At least 60 characters: why only the key survives and each other option fails.' }
      }
    } } }
  };
}

function formatStudyQuestionsForChat(ctx, questions) {
  var multi = (ctx.passages || []).length > 1;
  var blocks = questions.map(function(question, index) {
    var stem = question.q;
    if (multi && question.passage && !/^\(?P\d/i.test(stem)) stem = '(' + String(question.passage).trim() + ') ' + stem;
    return formatQuestionBlock({ q:stem, options:question.options }, index + 1);
  });
  var slots = questions.map(function(_question, index) { return (index + 1) + '-[your choice]'; }).join(', ');
  return 'Questions\n\n' + blocks.join('\n\n') + '\n\nReply in one line using this format: ' + slots + '. I already have the key and will check each choice against the material.';
}

async function generateQuestionsFromStudyMaterial(text, turn) {
  var ctx = ensureStudyConfigured() ? MargStudy.getContext() : null;
  if (!ctx) return false;
  var materialSection = ctx.section === 'dilr' ? 'dilr' : ctx.section === 'qa' ? 'qa' : 'varc';
  var auditSection = materialSection === 'varc' ? 'rc' : materialSection;
  var count = Math.max(1, Math.min(8, turn.count || (ctx.passages && ctx.passages.length > 1 ? Math.min(8, ctx.passages.length * 2) : 4)));
  var diagnosis = { intent:'study_activity', responseShape:'study', studyTurnType:'generate_questions', submittedAnswerText:text };
  showTyping(text, diagnosis, false);
  var failure = '';
  try {
    await MargStudy.loadLibrary();
    var memorySection = materialSection === 'varc' ? 'rc' : materialSection;
    var avoidNotes = '';
    var accepted = null;
    for (var attempt = 0; attempt < 2 && !accepted; attempt++) {
      var prompt = MargStudy.buildQuestionsFromMaterialPrompt(ctx, {
        count:count,
        avoidBlock:MargStudy.avoidBlock(memorySection, 6) + avoidNotes,
        exemplars:MargStudy.exemplarBlock(materialSection, ctx.id),
        stepsBlock:MargStudy.stepsForPrompt(ctx, 8)
      });
      var request = buildGeminiRequest('You are an expert CAT question setter. Return only valid JSON. Check each key before you return it, and do not describe the keys as independently verified.' + getDateContext(), [{ role:'user', content:prompt }], 16384, 'application/json', getStudyQuestionSchema(count));
      var response = await fetchWithTimeout(WORKER_URL, { method:'POST', headers:{ 'Content-Type':'application/json' }, body:JSON.stringify(request) }, 120000);
      var payload = await response.json();
      if (isGeminiStructuredResponseTruncated(payload)) throw new SyntaxError('Question JSON was truncated');
      var parsed = parseGeneratedJson(getGeminiText(payload));
      var list = parsed && Array.isArray(parsed.questions) ? parsed.questions : [];
      list.forEach(normalizeCorrectIndex);
      var shapeIssues = [];
      if (list.length !== count) shapeIssues.push('exactly ' + count + ' questions are required');
      list.forEach(function(question, index) {
        if (!isValidTimedTestQuestion(question)) shapeIssues.push('question ' + (index + 1) + ' is incomplete or has a duplicate option');
        if (String(question && question.explanation || '').trim().length < 30) shapeIssues.push('question ' + (index + 1) + ' has no usable explanation');
      });
      var candidate = materialSection === 'varc'
        ? { sets:[{ passage:ctx.text, difficulty:'CAT', topic:'Student material', questions:list }] }
        : materialSection === 'dilr'
          ? { sets:[{ setup:ctx.text, difficulty:'CAT', set_title:'Student set', questions:list }] }
          : { questions:list.map(function(question) { return Object.assign({}, question, { solution:question.explanation }); }) };
      var repeats = shapeIssues.length ? [] : MargStudy.findRepeats(memorySection, materialSection === 'varc' ? { sets:[{ questions:list }] } : candidate);
      if (shapeIssues.length || repeats.length) {
        avoidNotes = '\nPREVIOUS DRAFT REJECTED: ' + shapeIssues.concat(repeats).join('; ') + '. Write different questions that test different skills.';
        continue;
      }
      var audit = await auditGeneratedCATContent(auditSection, candidate, null, [], { timeoutMs:110000 });
      if (!audit.valid) { avoidNotes = '\nPREVIOUS DRAFT FAILED THE INDEPENDENT ANSWER CHECK: ' + (audit.issues || []).join('; ') + '. Fix the ambiguity or the key.'; continue; }
      var audited = audit.correctedData || candidate;
      var auditedList = audited.sets ? audited.sets[0].questions : audited.questions;
      // A second, independent solve must land on the same option. Two solvers
      // that disagree mean the item is ambiguous or mis-keyed, so it is dropped.
      var disagreements = list.map(function(question, index) { return auditedList[index] && auditedList[index].correct !== question.correct ? index + 1 : 0; }).filter(Boolean);
      if (disagreements.length) { avoidNotes = '\nPREVIOUS DRAFT REJECTED: an independent solve chose a different option for question ' + disagreements.join(', ') + '. Each question must have exactly one defensible option.'; continue; }
      accepted = audited;
    }
    if (!accepted) throw new Error('Study questions did not pass the independent check');
    var finalQuestions = accepted.sets ? accepted.sets[0].questions : accepted.questions;
    var visible = formatStudyQuestionsForChat(ctx, finalQuestions);
    hideTyping();
    addMessage('marg', renderMentorStructuredText(visible), true);
    conversationHistory.push({ role:'assistant', content:visible });
    if (!isGuestMode) saveChatMessage('assistant', visible);
    MargStudy.recordStep('marg', 'questions', 'Generated ' + finalQuestions.length + ' original questions on this material.');
    MargStudy.updateContext({ questionsGenerated:(ctx.questionsGenerated || 0) + finalQuestions.length, pendingTask:'' });
    MargStudy.recordPractice(memorySection, materialSection === 'varc' ? { sets:[{ questions:finalQuestions }] } : accepted);
    var storedType = materialSection;
    storeActiveGeneratedExercise({ id:'exercise-study-' + Date.now(), type:storedType, source:'study-material', title:'Questions on your ' + (materialSection === 'varc' ? 'passage' : materialSection === 'dilr' ? 'set' : 'material'), purpose:'Check the student against the material they supplied. A second model pass agreed with the keys, and that agreement does not prove the questions are correct.', hypothesis:null, validationVerdict:{ status:answerKeyVerificationStatus(audit.verification), verification:audit.verification || null }, content:Object.assign({}, accepted, { exerciseText:visible }) });
    return true;
  } catch (error) {
    failure = error && error.message || 'failed';
    console.error('Study question generation failed:', failure);
  }
  hideTyping();
  var notice = 'I could not get a clean checked round of questions on this material just now. Your material is still saved here, so send the same request again and I will build them from it.';
  addMessage('marg', escapeChatHtml(notice), true);
  conversationHistory.push({ role:'assistant', content:notice });
  if (!isGuestMode) saveChatMessage('assistant', notice);
  return true;
}

async function sendMessage(fromQueue, submissionOptions) {
  const mockOverlay = document.getElementById('mock-onboarding-overlay');
  const mockVisible = mockOverlay && mockOverlay.style.display === 'flex';
  var inConversationalOnboarding = !onboardingComplete && conversationHistory.length > 0;
  var homepageIntentForSend = null;
  if (submissionOptions && submissionOptions.homepageIntentId && typeof loadHomepageIntent === 'function') {
    var storedHomepageIntent = loadHomepageIntent();
    if (storedHomepageIntent && storedHomepageIntent.id === submissionOptions.homepageIntentId) homepageIntentForSend = storedHomepageIntent;
  }
  var reuseHomepageUserMessage = !!(homepageIntentForSend && submissionOptions && submissionOptions.reuseUserMessage);
  const input = document.getElementById('user-input');
  const typedText = input.value.trim();
  const imageAttachments = pendingImageAttachments.filter(function(item) { return item && item.data; }).slice();
  const hasImages = imageAttachments.length > 0;
  const hasContent = !!(typedText || hasImages);
  const text = typedText || (imageAttachments.length > 1 ? 'Please analyze these images in page order.' : 'Please analyze this image.');
  var reuseFailedUserMessage = !!(!reuseHomepageUserMessage && !hasImages && lastFailedOutgoingMessage && lastFailedOutgoingMessage.text === text &&
    conversationHistory.length && conversationHistory[conversationHistory.length - 1].role === 'user' &&
    String(conversationHistory[conversationHistory.length - 1].content || '').trim() === text);
  if (lastFailedOutgoingMessage && lastFailedOutgoingMessage.text !== text) lastFailedOutgoingMessage = null;
  const duplicate = !reuseHomepageUserMessage && !reuseFailedUserMessage && !hasImages && text === lastSentMessage && (Date.now() - lastSentAt) < 4000;
  const chatReady = !!(onboardingComplete || mockVisible || inConversationalOnboarding || homepageIntentForSend);
  const submissionDecision = getMessageSubmissionDecision({
    hasContent:hasContent,
    isLoading:isLoading,
    queueFull:!!queuedOutgoingMessage,
    chatReady:chatReady,
    duplicate:duplicate,
    fromQueue:!!fromQueue
  });

  if ((typeof imagePreparationInFlight !== 'undefined' && imagePreparationInFlight > 0) || pendingImageAttachments.some(function(item) { return item && (item.status === 'preparing' || item.status === 'uploading'); })) {
    showComposerStatus('Please wait until every selected image says Attached before sending.', 'info', true);
    updateComposerControls();
    return;
  }
  var unusableImage = pendingImageAttachments.find(function(item) { return item && item.status === 'failed' && !item.data; });
  if (unusableImage) {
    showComposerStatus('Remove or retry the failed image before sending. Marg will not answer as if it received it.', 'error', true);
    return;
  }

  if (submissionDecision === 'queue' || submissionDecision === 'queue_full' || submissionDecision === 'loading_empty') {
    queueCurrentComposerMessage();
    return;
  }
  if (submissionDecision === 'empty') {
    showComposerStatus('Type a message or attach an image before sending.', 'info');
    return;
  }
  if (submissionDecision === 'chat_not_ready') {
    saveCurrentChatDraft();
    showComposerStatus('Marg is still opening the conversation. Your draft is saved—send it once the first message appears.', 'info', true);
    return;
  }
  if (submissionDecision === 'duplicate') {
    showComposerStatus('That message was already sent. Marg is working on it.', 'info');
    return;
  }
  if (!checkGuestLimit()) {
    showComposerStatus('The guest-message limit has been reached. Sign in to keep this conversation going.', 'info', true);
    return;
  }

  showComposerStatus('', 'info');
  lastSentMessage = text; lastSentAt = Date.now();
  input.value = ''; input.style.height = 'auto';
  saveCurrentChatDraft();
  try {
    isLoading = true;
    updateComposerControls();
    // Quick replies are choices for the immediately preceding mentor turn.
    // Once the student types a normal message, stale choices must disappear so
    // an old “Something else” cannot hijack the new RC conversation.
    // Image turns always replace any old diagnostic/practice quick replies.
    // Otherwise stale VARC chips can appear to belong to an image failure.
    if (!fromQueue || hasImages) removeConversationalOptions();
    if (isGuestMode) { guestMessageCount++; updateGuestBanner(); }
    var storedImageMarker = hasImages ? '\n[' + imageAttachments.length + ' images attached in page order: ' + imageAttachments.map(function(item) { return item.name; }).join(', ') + ']' : '';
    var storedUserText = text + storedImageMarker;
    if (!reuseHomepageUserMessage && !reuseFailedUserMessage) {
      addMessage('user', hasImages ? buildImageUserMessageHtml(typedText, imageAttachments) : escapeChatHtml(text).replace(/\n/g, '<br>'));
      conversationHistory.push({ role: 'user', content: storedUserText });
      if(typeof maybeRenameActiveTopicFromMessage==='function')maybeRenameActiveTopicFromMessage(typedText);
      capturePersonalGoalDetails(text);
      captureProgressiveProfileDetails(text);
      detectAndSaveMockScores(text);
      if (!isGuestMode) saveChatMessage('user', storedUserText);
      if (hasImages && typeof linkQuestionImagesToMessage === 'function') {
        var savedUserEntry = conversationHistory[conversationHistory.length - 1];
        linkQuestionImagesToMessage(imageAttachments, savedUserEntry && savedUserEntry.id).catch(function() {});
      }
      if (!hasImages && isMeaningfulCatSpecificMessage(text)) {
        recordEngagementEvent('meaningful_cat_question', {
          intent:detectMentorIntent(text),
          text_hash:simpleStableHash(text)
        }, 'question-' + simpleStableHash(text) + '-' + getEngagementSessionKey());
      }
      if (hasImages) removePendingImageAttachment();
    } else if (!conversationHistory.some(function(item) { return item && item.role === 'user' && String(item.content || '').trim() === text; })) {
      conversationHistory.push({ role:'user', content:text });
    }
    if (homepageIntentForSend && typeof markHomepageIntentSubmitted === 'function') homepageIntentForSend = markHomepageIntentSubmitted(homepageIntentForSend) || homepageIntentForSend;

  loadActiveGeneratedExercise();
  // Material the student supplies is the active study source. Decide that before
  // saved-question retrieval, intake gates and practice launchers can see it.
  var studyTurn = hasImages || !onboardingComplete ? { type:'none', owns:false } : getStudyTurn(text);
  var studyOwned = !!studyTurn.owns;
  if (studyOwned && studyTurn.type === 'material') adoptStudyMaterial(studyTurn);
  if (hasImages) showComposerStatus('Image attached — Marg is reading and indexing the visible questions…', 'info', true);
  var questionResolution = typeof prepareQuestionContextForTurn === 'function'
    ? await prepareQuestionContextForTurn(text, imageAttachments)
    : { blocked:false, attachments:imageAttachments, directive:'' };
  if (questionResolution && questionResolution.blocked) {
    removeConversationalOptions();
    var questionBlockReply = String(questionResolution.reply || 'I cannot identify that question safely. Please re-upload the complete question.');
    addMessage('marg', renderMentorStructuredText(questionBlockReply));
    conversationHistory.push({ role:'assistant', content:questionBlockReply });
    if (!isGuestMode) saveChatMessage('assistant', questionBlockReply);
    showComposerStatus('', 'info');
    return;
  }
  if (hasImages) showComposerStatus('', 'info');
  var effectiveImageAttachments = questionResolution && Array.isArray(questionResolution.attachments) ? questionResolution.attachments : imageAttachments;
  var effectiveHasImages = effectiveImageAttachments.length > 0;
  if (!effectiveHasImages && !studyOwned && cancelActiveExerciseForChat(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && maybeHandlePrivacyRequest(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && maybeHandleCurrentChatScoreRecall(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && (maybeHandleStopSummary(text) || maybeHandleCatDurationQuestion(text))) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && maybeHandleAmbiguousShortInput(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && routePendingExternalQuestionReply(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && gateFreshExternalQuestion(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && maybeHandleSectionChoicePrompt(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && maybeReplayActiveExercise(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }
  noteMentorPlanCompletionClaim(text);
  var predictionValidationReply = isPredictionValidationReply(text);
  if (!studyOwned && !pendingExternalQuestionTurnMode && (isAnswerReviewRequest(text) || predictionValidationReply)) markActiveExerciseAttempt(text, predictionValidationReply);

  if (!effectiveHasImages && !studyOwned && maybeCompleteHypothesisExperimentReview(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && maybeCompleteVerifiedAnswerReview(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!effectiveHasImages && !studyOwned && (await maybeGenerateConversationalRC(text) || maybeLaunchExplicitPracticeRequest(text) || maybeHandlePracticeProductQuestion(text) || await maybeStartHypothesisExperiment(text) || await maybeStartSavedDiagnosticCheck(text) || maybeHandleTimetableIntake(text) || maybeLeadWithProgression(text))) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  // Explicit new-topic requests enter the same fast diagnostic used on day one.
  // Confirmed topics continue directly to mentoring and are never re-asked here.
  if (!effectiveHasImages && !studyOwned && !window._timetableRoutineJustCaptured && await maybeStartGuidedExperienceFromMessage(text)) {
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (studyOwned && studyTurn.type === 'generate_questions') {
    var studyQuestionsDone = await generateQuestionsFromStudyMaterial(text, studyTurn);
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
    return;
  }

  if (!onboardingComplete && conversationHistory.length <= 10) {
    var conversationalResponseCompleted = await sendConversationalMessage(text, 'typed', effectiveImageAttachments, questionResolution);
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function' && conversationalResponseCompleted !== false) completeHomepageIntent(homepageIntentForSend);
    else if (homepageIntentForSend && typeof failHomepageIntent === 'function') failHomepageIntent(homepageIntentForSend);
    return;
  }

  const mentorAnalysis = anchorMentorAnalysisToImageContext(buildDiagnosisDirective(text), text, effectiveImageAttachments);
  if (questionResolution && questionResolution.directive) mentorAnalysis.directive += questionResolution.directive;
  if (pendingExternalQuestionTurnMode === 'review') {
    mentorAnalysis.diagnosis.intent = 'answer_review';
    mentorAnalysis.directive += getPendingExternalQuestionContext();
  } else if (pendingExternalQuestionTurnMode === 'solution' || pendingExternalQuestionTurnMode === 'hint') {
    mentorAnalysis.directive += getPendingExternalQuestionContext();
  }
  const studyReply = studyOwned && mentorAnalysis.diagnosis.responseShape === 'study';
  const useWebGrounding = studyReply ? false : shouldUseWebGrounding(text, mentorAnalysis.diagnosis);
  if (studyReply) recordStudyStudentStep(studyTurn, text);
  showTyping(text, mentorAnalysis.diagnosis, useWebGrounding);
  // Recent turns are already supplied in requestHistory. Do not duplicate them
  // inside the system instruction on every authenticated chat request.
  profileContext = buildMentorTurnContext(text, mentorAnalysis, { surface:'chat', useWebGrounding:useWebGrounding });
  try {
    const mentorMaxTokens = getMentorResponseMaxTokens(mentorAnalysis.diagnosis);
    const mentorTimeout = getMentorRequestTimeout(mentorAnalysis.diagnosis, useWebGrounding);
    let requestHistory = buildHistoryWithImageAttachment(conversationHistory, effectiveImageAttachments, text, mentorAnalysis.diagnosis, { surface:'chat', hasImage:effectiveHasImages });
    if (useWebGrounding) requestHistory = trimHistoryForGroundedRequest(requestHistory);
    const mentorRequest = buildGeminiRequest(SYSTEM_PROMPT + profileContext, requestHistory, mentorMaxTokens);
    // Reasoning shares the output cap. Study text is long, so keep reasoning light.
    if (studyReply) mentorRequest.generationConfig.thinkingConfig = { thinkingLevel:'low' };
    enableWebGrounding(mentorRequest, useWebGrounding);
    const response = await fetchWithTimeout(WORKER_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(mentorRequest) }, mentorTimeout);
    const data = await response.json();
    var mentorModelText = await resolveStudyReply(data, mentorRequest, mentorTimeout, { allowPartial:studyReply });
    if (mentorModelText == null) {
      var truncatedMentorError = new Error('Mentor output hit the token ceiling');
      truncatedMentorError.name = 'GeminiEmptyResponseError';
      throw truncatedMentorError;
    }
    let reply = applyMentorResponseGuard(preventStructuredOutputLeak(captureMentorHypotheses(mentorModelText, text, mentorAnalysis.diagnosis).text), mentorAnalysis.diagnosis);
    if (!studyReply) {
      reply = stabilizeAndRememberMission(reply, text);
      reply = suppressUnrelatedActivePlanReminder(reply, text);
      reply = suppressUnrelatedExerciseContinuation(reply, text);
    }
    if (questionResolution && questionResolution.question && typeof verifyQuestionResponseDraft === 'function') {
      reply = await verifyQuestionResponseDraft(reply, text, effectiveImageAttachments, questionResolution);
      reply = guardCleanSolvedQuestionResponse(guardDeterministicArithmeticEqualities(reply), mentorAnalysis.diagnosis);
    }
    if (typeof finaliseQuestionResponse === 'function') reply = finaliseQuestionResponse(reply, questionResolution);
    finalizeMentorPlanCompletionReview(text, reply);
    markPersonalGoalFollowUpIfAsked(reply);
    markProgressiveProfileFollowUpIfAsked(reply);
    hideTyping();
    applyPredictionValidationVerdict(reply);
    reply = stripInternalMentorTags(reply);
    reply = appendGroundingSources(reply, data);
    reply = finalizeMentorSavedText(reply, mentorAnalysis.diagnosis);
    if (!studyReply) markExerciseReviewCompleted(reply);
    if (studyReply) recordStudyMentorStep(studyTurn, reply);
    if (!mentorAnalysis.diagnosis.gradingIntegrityRepaired && mentorAnalysis.diagnosis.intent === 'answer_review' && !(activeGeneratedExercise && activeGeneratedExercise.hypothesis) && hasVerifiedRepeatedAnswerError(text)) recordBehaviorPattern(activeGeneratedExercise ? activeGeneratedExercise.type : 'general', reply, text, 'answer-review');
    conversationHistory.push({ role: 'assistant', content: reply });
    if (!isGuestMode) saveChatMessage('assistant', reply);
    const formatted = renderGroundingSourcesForChat(renderMentorStructuredText(reply));
    addMessage('marg', formatted);
    lastFailedOutgoingMessage = null;
    if (!studyReply) {
      checkAndRenderMargOptions(reply);
      checkAndRenderTestPrompt(reply);
      checkAndLogPracticeVolume(reply);
      if (!margPendingConversationOptions) presentHypothesisExperimentOffer();
    }
    completePendingExternalQuestionTurn();
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
  } catch (e) {
    hideTyping();
    if (isGeminiServiceError(e)) {
      completeMentorTurnWithLocalRecovery(text, mentorAnalysis.diagnosis, useWebGrounding, e);
      if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
      return;
    }
    let fallbackReply = buildPredictionValidationFallback(text) || (mentorAnalysis.diagnosis.intent === 'answer_review' ? (buildLocalAnswerCheck(text) || buildMentorFallbackReply(mentorAnalysis.diagnosis)) : buildMentorFallbackReply(mentorAnalysis.diagnosis));
    fallbackReply = stabilizeAndRememberMission(reduceAssistantStyleLanguage(enforceIndiaTimeGreeting(correctCalendarReferences(fallbackReply))), text);
    fallbackReply = suppressUnrelatedActivePlanReminder(fallbackReply, text);
    fallbackReply = suppressUnrelatedExerciseContinuation(fallbackReply, text);
    finalizeMentorPlanCompletionReview(text, fallbackReply);
    applyPredictionValidationVerdict(fallbackReply);
    fallbackReply = stripInternalMentorTags(fallbackReply);
    fallbackReply = finalizeMentorSavedText(fallbackReply, mentorAnalysis.diagnosis);
    markExerciseReviewCompleted(fallbackReply);
    addMessage('marg', fallbackReply);
    conversationHistory.push({ role: 'assistant', content: fallbackReply });
    if (!isGuestMode) saveChatMessage('assistant', fallbackReply);
    lastFailedOutgoingMessage = null;
    completePendingExternalQuestionTurn();
    if (homepageIntentForSend && typeof completeHomepageIntent === 'function') completeHomepageIntent(homepageIntentForSend);
  }
  } catch (sendStateError) {
    hideTyping();
    console.error('Message submission state failed:', sendStateError);
    if (!homepageIntentForSend) addMentorLeadMessage('That message hit a temporary send problem, but the chat is unlocked and your message is still visible above. Try once more—I will continue from it.');
    showComposerStatus('The send failed, but the composer has recovered. You can try again now.', 'error', true);
    if (homepageIntentForSend && typeof failHomepageIntent === 'function') failHomepageIntent(homepageIntentForSend, sendStateError);
  } finally {
    isLoading = false;
    pendingExternalQuestionTurnMode = '';
    window._timetableRoutineJustCaptured = false;
    updateComposerControls();
    if (queuedOutgoingMessage) setTimeout(flushQueuedComposerMessage, 0);
    else if (typeof hasPendingHomepageIntent === 'function' && hasPendingHomepageIntent()) scheduleHomepageIntentDispatch(150);
    else if (hasPendingDeepLinkQuestion()) schedulePendingDeepLinkQuestionDispatch(150);
    else {
      if (typeof maybePresentCommunityInvite === 'function') maybePresentCommunityInvite();
      focusComposer();
    }
  }
}

